INSERT INTO `YTxejLABtRB1_element_notes` (`id`, `type`, `text`) VALUES
(1, 'template', '[[$MiniFix.main?]]\n<!doctype html>\n<html lang=\"ru\">\n<head>\n{$_modx->getChunk(\'!Meta\')}\n{ignore}<link rel=\"stylesheet\" href=\"/tpl/css/main.min.css\">{/ignore}\n[[+MinifyX.javascript]]\n</head>\n<body class=\"uk-height-viewport\">\n<div class=\"uk-offcanvas-content\">\n  {include \'Home.Header\'}\n  {include \'Home.Content\'}\n  {include \'Home.Garanty\'}\n  {include \'Home.News\'}\n  {include \'Home.Discount\'}\n  <div class=\"uk-section uk-section-default\">\n    {include \'Home.Usage\'}\n    {include \'Home.Reason\'}\n  </div>\n  {include \'Home.More\'}\n  {include \'Home.Folio\'}\n  {include \'Home.Expert\'}\n  <section class=\"uk-section uk-section-default uk-section-large master\">\n    <div class=\"uk-container\">\n      {include \'Home.Master\'}\n      {include \'Home.Projects\'}\n    </div>\n  </section>\n  {include \'Form.Inline\'}\n  {include \'Home.Proccess\'}\n  {include \'Home.Map.Google\'}\n  {include \'Footer\'}\n  {include \'offcanvas\'}\n</div>\n{include \'Form.callbackModal\'}\n</body>\n</html>\n[[+MinifyX.css]]'),
(37, 'chunk', '<header class=\"header uk-light uk-background-primary uk-position-relative\">\n  <div class=\"uk-position-cover uk-background-cover uk-background-fixed\" style=\"background-image: url(tpl/img/pattern-2.svg)\"></div>\n	<div class=\"uk-position-cover uk-overlay-primary\"></div>\n	<div class=\"uk-section uk-section-large uk-position-relative uk-position-z-index header-content\">\n		<div class=\"uk-container\">\n			<div class=\"uk-grid uk-flex-center uk-text-center\" uk-grid>\n				<div class=\"uk-width-1-1 uk-width-3-4@m\">\n					<h1 class=\"uk-heading-primary text-light\">{$_modx->resource.pagetitle}</h1>\n					<p class=\"uk-text-large text-light\">{$_modx->resource.introtext}</p>\n				</div>\n				<div class=\"uk-width-1-1\">\n					<button type=\"button\" class=\"uk-button uk-button-large uk-button-default uk-border-rounded\" uk-toggle=\"target: #callback; center: true\">Позвонить</button>\n				</div>\n			</div>\n		</div>\n	</div>\n	<nav class=\"uk-navbar-container uk-navbar-transparent uk-position-z-index uk-position-top uk-flex-middle\" uk-navbar uk-sticky>\n		<div class=\"uk-navbar-left\">\n			<a class=\"uk-navbar-item uk-logo uk-visible@m\" href=\"{$_modx->config.site_url}\">Logo</a> <a class=\"uk-navbar-toggle uk-hidden@m\" href=\"#offcanvas-nav\" uk-toggle><span uk-navbar-toggle-icon></span> <span class=\"uk-margin-small-left\">МЕНЮ</span> </a>\n		</div>\n		<div class=\"uk-navbar-center\">\n			<ul class=\"uk-navbar-nav uk-visible@m\">\n			  {$_modx->getChunk(\'!Nav.top\')}\n			</ul>\n		</div>\n		<div class=\"uk-navbar-right\"><a class=\"uk-navbar-item uk-logo text-light\" href=\"#\">{$_modx->config.lp_phone}</a></div>\n	</nav>\n</header>'),
(33, 'chunk', '<div class=\"uk-inline  uk-width-1-1\" uk-form-custom=\"target: true\">\n                  <input type=\"file\"> <span class=\"uk-form-icon uk-form-icon-flip\" uk-icon=\"icon: cloud-upload\"></span>\n                  <input class=\"uk-input uk-width-1-1 uk-form-large uk-border-rounded\" type=\"text\" placeholder=\"Приложите файл, если есть\" disabled>\n                </div>\n                \n<div class=\"uk-inline uk-width-1-1\">[[!YandexDiskUploader? &inputId=`af_files`]]</div>'),
(88, 'chunk', '<div class=\"uk-width-1-1 uk-width-1-2@m\">\n	<div class=\"uk-inline-clip uk-transition-toggle uk-box-shadow-bottom uk-border-rounded\">\n		<img src=\"[[+thumb]]\" class=\"uk-transition-scale-up uk-transition-opaque\" width=\"[[+width]]\" height=\"[[+height]]\" alt=\"[[+title]]\">\n		<div class=\"uk-overlay uk-transition-fade uk-position-small uk-border-rounded uk-overlay-primary uk-position-cover uk-flex uk-flex-center uk-flex-middle uk-light\">\n			<span uk-icon=\"icon: play-circle; ratio: 4\"></span></div>\n		[[+isVideo:is=`1`:then=`<span class=\"uk-position-top-right uk-label uk-margin-top uk-margin-right\"><span uk-icon=\"icon: clock; ratio: 0.7\"></span> [[+duration]]</span>`]]\n		<a href=\"[[+url]]\" class=\"uk-position-cover\" title=\"[[+title]]\" data-caption=\"[[+title]]\"></a>\n	</div>\n</div>\n<div class=\"uk-width-1-1 uk-width-1-2@m\">\n	<p class=\"uk-h3 uk-margin-remove\">[[+title]]</p>\n	[[+description:notempty=`<p class=\"uk-margin-small-top uk-text-small\">[[+description]]</p>`]]\n</div>'),
(60, 'chunk', '{$_modx->runSnippet(\'pdoMenu\', [\n  \'parents\' => 0,\n  \'resources\' => \'-1\',\n  \'fastMode\' => 1,\n  \'level\' => 0,\n  \'cache\' => 1,\n  \'showHidden\' => 0,\n	\'countChildren\' => 0,\n  \'hereClass\' => \'uk-active\',\n	\'lastClass\' => \'0\',\n	\'firstClass\' => \'0\',\n  \'tplOuter\' => \'@INLINE {{+wrapper}}\',\n  \'tpl\' => \'@INLINE <li {{+classes}}><a href=\"{{+link}}\" {{+attributes}}>{{+menutitle}}</a></li>\',\n	\'tplParentRow\' => \'@INLINE <li {{+classes}}><a href=\"{{+link}}\" {{+attributes}}>{{+menutitle}} <span class=\"uk-margin-small-left\" uk-icon=\"icon: chevron-down\"></span></a>\n	  {{+wrapper}}</li>\',\n	\'tplParentRowHere\' => \'\',\n	\'tplParentRowActive\' => \'\',\n	\'tplInner\' => \'@INLINE <div class=\"uk-navbar-dropdown uk-border-rounded\"><ul class=\"uk-nav uk-navbar-dropdown-nav\">{{+wrapper}}</ul></div>\',\n	\'tplInnerRow\' => \'@INLINE <li {{+classes}}><a href=\"{{+link}}\" {{+attributes}}>{{+menutitle}}</a></li>\',\n])}'),
(143, 'chunk', '<div class=\"uk-background-muted uk-flex uk-flex-middle uk-flex-center\" style=\"height: 500px\" id=\"map\"></div>\n{ignore}\n<script>\n$(document).ready(function () { \n   $.getScript(\'https://api-maps.yandex.ru/2.1/?lang=ru-RU\').done(function (script, textStatus) {\n    ymaps.ready(init);\n      function init () { \n        var myMap = new ymaps.Map(\'map\', { \n            center: [ 53.028836,38.424347 ],\n            zoom: 4,\n            controls: [\'zoomControl\'],\n        }),\n        objectManager = new ymaps.ObjectManager({\n          clusterize: true,\n          checkZoomRange:true,\n          gridSize: 48\n        });\n        myMap.behaviors.disable(\'scrollZoom\');\n        objectManager.objects.options.set(\'preset\', \'islands#redDotIcon\');\n        objectManager.clusters.options.set(\'preset\', \'islands#redClusterIcons\');\n        myMap.geoObjects.add(objectManager);\n        objectManager.add({ \"type\": \"FeatureCollection\", \"features\": [\n        [[!getImageList?\n          &tvname=`MapPoints`\n          &limit=`0`\n          &tpl=`Maps.Point.Row`\n          &docid=`1`\n          &outputSeparator=`, `\n        ]]\n        ]});\n    }\n  });\n});\n</script>\n{/ignore}'),
(119, 'chunk', '<div class=\"header-top\">\n  <div class=\"uk-container\">\n    <div class=\"uk-flex-middle\" uk-grid>\n      <div class=\"uk-width-auto@m uk-width-1-1 uk-text-center\">\n        <a href=\"index.html\" class=\"header-top--logo\"><img src=\"{\'lp_logo\' | config}\" width=\"216\" height=\"47\"></a>\n      </div>\n      <div class=\"uk-width-expand uk-visible@xl\">\n        <div class=\"header-top--address\">\n          <div class=\"uk-grid-small uk-flex-middle\" uk-grid>\n            <div class=\"uk-width-expand uk-text-right\"><span class=\"sprite--header__map-pin\"></span></div>\n            <div class=\"uk-width-auto\">{\'lp_address_city\' | config}{if \'lp_address_metro\' | config ?}<br> (метро: {\'lp_address_metro\' | config}){/if}</div>\n          </div>\n        </div>\n      </div>\n      <div class=\"uk-width-expand uk-hidden@xl\"></div>\n      <div class=\"uk-width-auto uk-visible@m\">\n        <header class=\"header-top--callback\">\n          <div class=\"header-top--callback__phone\"><span class=\"sprite--header__phone\"></span> <a class=\"uk-link-reset\" href=\"tel:{\'lp_phone\' | config | replace : \"(\" : \"\" | replace : \")\" : \"\" | replace : \"-\" : \"\" | replace : \" \" : \"\"}\">{\'lp_phone\' | config}</a></div>\n          <div class=\"header-top--callback__descr\">{\'lp_phone_2\' | config}</div>\n        </header>\n      </div>\n      <div class=\"uk-width-auto uk-visible@l\">\n        <button type=\"button\" class=\"uk-button uk-button-default\" uk-toggle=\"target: #callback\">Заказать звонок</button>\n      </div>\n    </div>\n  </div>\n</div>'),
(166, 'chunk', '<li>\n  <aside class=\"product\">\n    <div class=\"product-image uk-background-contain js-lozad\" data-background-image=\"{$thumbwidth}\">\n      <canvas width=\"600\" height=\"600\"></canvas>\n    </div>\n    <div class=\"product-descr\">{$pagetitle}</div>\n    <div class=\"product-price\">\n      {$price}<span>рублей</span>\n    </div>\n    <div class=\"product-action\">\n      <button type=\"button\" class=\"uk-button uk-button-danger\">Заказать</button>\n    </div>\n  </aside>\n</li>'),
(45, 'chunk', '<div class=\"uk-section uk-section-small uk-section-muted\" style=\"border-top: 1px solid #e9e9e9\">\n	<div class=\"uk-container\">\n		<div class=\"uk-grid uk-flex-center\" uk-grid>\n		  {if $_modx->resource.parent == 52 || $_modx->resource.parent == 84}\n			<div class=\"uk-width-1-1 uk-width-auto@m uk-visible@m\">\n			  <div class=\"uk-card uk-card-small uk-card-default uk-boxshadow-small\">\n			    <div class=\"uk-card-header\">\n            <p class=\"uk-card-title\">\n              {if $_modx->resource.parent == 52}{52 | resource : \'pagetitle\'}{/if}\n              {if $_modx->resource.parent == 84}{84 | resource : \'pagetitle\'}{/if}\n            </p>\n          </div>\n          <div class=\"uk-card-body\">\n            <ul class=\"uk-nav-default uk-nav-parent-icon\" uk-nav>\n              {$_modx->runSnippet(\'pdoMenu\', [\n                \'parents\' => $_modx->resource.parent,\n                \'resources\' => \'\',\n                \'fastMode\' => 1,\n                \'level\' => 0,\n                \'cache\' => 1,\n                \'showHidden\' => 0,\n              	\'countChildren\' => 0,\n                \'hereClass\' => \'uk-active\',\n              	\'lastClass\' => \'0\',\n              	\'firstClass\' => \'0\',\n                \'tplOuter\' => \'@INLINE {{+wrapper}}\',\n                \'tpl\' => \'@INLINE <li {{+classes}}><a href=\"{{+link}}\" {{+attributes}}>{{+menutitle}}</a></li>\'\n              ])}\n            </ul>\n          </div>\n			  </div>\n    	</div>\n    	{/if}\n			<div class=\"uk-width-1-1 uk-width-expand@m\">\n			  <h1 class=\"uk-h1 uk-text-center\">{$_modx->resource.pagetitle}</h1>\n			  <hr class=\"title-divider\">\n  			{$_modx->resource.content}\n  			{if $_modx->resource.showChildrens == 2}\n      	<div class=\"uk-width-1-1\">\n    			{$_modx->getChunk(\'!Info.Content.Childrens\')}\n  			</div>\n  			{/if}\n  			<div class=\"uk-grid uk-flex-middle\" uk-grid uk-lightbox=\"type: video; animation: scale; video-autoplay: true\">\n    		  {$_modx->runSnippet(\'ResVideoGallery\', [\n            \'resources\' => $_modx->resource.id,\n            \'limit\' => 0,\n            \'ajax\' => 0,\n            \'tpl\' => \'VideoGalleryHome\',\n            \'tplRow\' => \'VideoGalleryHome.Row\',\n            \'tplEmbed\' => \'VideoGalleryEmbedTpl\'\n          ])}\n    		</div>\n    	</div>\n    	{if $_modx->resource.showGallery == 1}\n    	<div class=\"uk-width-1-1\">\n  			{$_modx->getChunk(\'!Info.Content.Gallery\')}\n			</div>\n			{/if}\n			{if $_modx->resource.parent == 51}\n			<div class=\"uk-width-1-1\">\n			  {$_modx->getChunk(\'!Info.Pagination.Publishedon\')}\n			</div>\n			{/if}\n			{if $_modx->resource.underContent ?}\n			<div class=\"uk-width-1-1\">{$_modx->resource.underContent}</div>\n			{/if}\n		</div>\n	</div>\n</div>');
