(19, 0, 0, 'resVideoGalleryFormTpl', '', 0, 18, 0, '<form action=\"[[~[[*id]]]]\" class=\"js-rvg-form rvg-form\" data-multiple=\"[[+multiple]]\">\r\n    <input type=\"hidden\" name=\"action\" value=\"add\">\r\n    <div class=\"js-rvg-form-notice rvg-form-notice\"></div>\r\n    <div class=\"js-rvg-form-container\">\r\n        <!-- rvg-form-video -->\r\n        <div class=\"js-rvg-form-video rvg-form-video\">\r\n            <div class=\"js-rvg-form-error rvg-form-error\"></div>\r\n            <label>[[%video.label.url]]\r\n                <div class=\"rvg-form-url-wrap\">\r\n                    <input type=\"url\" name=\"video[\'0\'][url]\" class=\"js-rvg-form-url\" placeholder=\"http:\\\\\" autofocus>\r\n                    [[+multiple:is=`1`:then=`\r\n                    <a href=\"#\" class=\"js-rvg-form-btn-remove rvg-form-btn-remove rvg-form-btn\" title=\"[[%video.btn.remove]]\">-</a>\r\n                    `]]\r\n                </div>\r\n            </label>\r\n            <div class=\"js-rvg-form-video-info rvg-form-video-info\">\r\n                <img src=\"\" class=\"js-rvg-form-thumb rvg-form-thumb\">\r\n                <label>[[%video.label.title]]\r\n                    <input type=\"text\" name=\"video[\'0\'][title]\" class=\"js-rvg-form-title\">\r\n                </label>\r\n                <label>[[%video.label.desc]]\r\n                    <textarea name=\"video[\'0\'][description]\" class=\"js-rvg-form-description\"></textarea>\r\n                </label>\r\n                <label>[[%video.label.tags]]\r\n                    <input type=\"text\" name=\"video[\'0\'][tags]\" class=\"js-rvg-form-tags\">\r\n                </label>\r\n            </div>\r\n        </div>\r\n        <!-- /.rvg-form-video -->\r\n    </div>\r\n    <button type=\"submit\" class=\"js-rvg-form-submit rvg-form-btn\">[[%video.btn.save]]</button>\r\n</form>\r\n[[+multiple:is=`1`:then=`\r\n<script id=\"rvg-tpl-form-video\" type=\"x-tmpl-rvg\">\r\n    <div class=\"js-rvg-form-video rvg-form-video\">\r\n        <div class=\"js-rvg-form-error rvg-form-error\"></div>\r\n        <label>[[%video.label.url]]\r\n            <div class=\"rvg-form-url-wrap\">\r\n                <input type=\"url\" name=\"video[\'{{num}}\'][url]\" class=\"js-rvg-form-url\" placeholder=\"http:\\\\\">\r\n                <a href=\"#\" class=\"js-rvg-form-btn-remove rvg-form-btn-remove rvg-form-btn\" title=\"[[%video.btn.remove]]\">-</a>\r\n             </div>\r\n        </label>\r\n        <div class=\"js-rvg-form-video-info rvg-form-video-info\">\r\n            <img src=\"\" class=\"js-rvg-form-thumb rvg-form-thumb\">\r\n            <label>[[%video.label.title]]\r\n                <input type=\"text\" name=\"video[\'{{num}}\'][title]\" class=\"js-rvg-form-title\">\r\n            </label>\r\n            <label>[[%video.label.desc]]\r\n                <textarea name=\"video[\'{{num}}\'][description]\" class=\"js-rvg-form-description\"></textarea>\r\n            </label>\r\n            <label>[[%video.label.tags]]\r\n                <input type=\"text\" name=\"video[\'{{num}}\'][tags]\" class=\"js-rvg-form-tags\">\r\n            </label>\r\n        </div>\r\n    </div>\r\n</script>\r\n`]]', 0, NULL, 0, ''),
(20, 0, 0, 'resVideoGalleryTpl', '', 0, 18, 0, '<div class=\"js-rvg-gallery rvg-gallery\" data-auto-play=\"[[+autoPlay]]\" data-tpl-embed=\"[[+tplEmbed]]\" data-tpl-tag=\"[[+tplTag]]\" >\r\n    <div class=\"js-rvg-holder rvg-gallery-holder\">\r\n        [[+rows]]\r\n    </div>\r\n    <div class=\"rvg-text-center\" style=\"[[+isMore:isnot=`1`:then=`display:none;`]]\">\r\n        <a href=\"#\" class=\"js-rvg-more rvg-btn rvg-btn-more\" data-params=\'[[+params]]\'>More video</a>\r\n    </div>\r\n</div>', 0, NULL, 0, ''),
(21, 0, 0, 'resVideoGalleryEmbedTpl', '', 0, 18, 0, '<div class=\"rvg-iframe\">\n    [[+embed]]\n</div>', 0, NULL, 0, ''),
(22, 0, 0, 'fiDefaultEmailTpl', 'The default chunk used for the email. Please do not edit this chunk, as this will be overwritten when updating FormIt.', 0, 24, 0, '<p>[[+fields]]</p>', 0, 'a:0:{}', 0, ''),
(23, 0, 0, 'fiDefaultFiarTpl', 'The default chunk used for the autoresponder email. Please do not edit this chunk, as this will be overwritten when updating FormIt.', 0, 24, 0, '<p>Hello [[+name]],</p>\n\n<p>Your message has been received. We will respond as soon as possible. Thank you for contacting us.</p>\n\n<p>NOTE: This is an automatic response; please do not respond to this message directly.</p>\n\n<p>Here is your message:<br />\n[[+message:nl2br]]</p>', 0, 'a:0:{}', 0, ''),
(24, 0, 0, 'fiDefaultOptGroupTpl', 'The default chunk used by the FormItCountryOptions snippet for the select optgroup. Please do not edit this chunk, as this will be overwritten when updating FormIt.', 0, 24, 0, '<optgroup label=\"[[+text]]\">\n    [[+options]]\n</optgroup>', 0, 'a:0:{}', 0, ''),
(25, 0, 0, 'fiDefaultOptionTpl', 'The default chunk used by the FormItCountryOptions snippet for the select option. Please do not edit this chunk, as this will be overwritten when updating FormIt.', 0, 24, 0, '<option value=\"[[+value]]\"[[+selected]]>[[+text]]</option>', 0, 'a:0:{}', 0, ''),
(26, 1, 0, 'Breadcrumb', '', 0, 3, 0, '{$_modx->runSnippet(\'pdoCrumbs\', [\n  \'showHome\' => 1,\n  \'showCurrent\' => 0,\n  \'fastMode\' => 1,\n	\'hideSingle\' => 1,\n  \'outputSeparator\' => \'\',\n  \'tplWrapper\' => \'@INLINE <ul itemscope=\"\" itemtype=\"http://schema.org/BreadcrumbList\" class=\"uk-breadcrumb uk-flex uk-flex-middle uk-flex-center\">{$output}</ul>\',\n  \'tplHome\' => \'@INLINE \n    <li><span itemscope=\"\" itemprop=\"itemListElement\" itemtype=\"http://schema.org/ListItem\" class=\"\">\n      <a title=\"{$menutitle}\" itemprop=\"item\" href=\"{$link}\" class=\"uk-button-text uk-link-reset\"><span itemprop=\"name\">{$menutitle}</span><meta itemprop=\"position\" content=\"{$menuindex}\"></a>\n    </span></li>\',\n  \'tpl\' => \'@INLINE \n    <li><span itemscope=\"\" itemprop=\"itemListElement\" itemtype=\"http://schema.org/ListItem\">\n      <a title=\"{$menutitle}\" itemprop=\"item\" href=\"{$link}\" class=\"uk-link-reset uk-button-text\"><span itemprop=\"name\">{$menutitle}</span><meta itemprop=\"position\" content=\"{$menuindex}\"></a>\n    </span></li>\',\n  \'tplCurrent\' => \'@INLINE \n    <li><span itemscope=\"\" itemprop=\"itemListElement\" itemtype=\"http://schema.org/ListItem\">\n      <span itemprop=\"name\">{$menutitle}</span><meta itemprop=\"position\" content=\"{$menuindex}\">\n    </span></li>\'\n])}', 0, 'a:0:{}', 0, ''),
(30, 1, 0, 'Form.callbackModal', '', 0, 5, 0, '[[!AjaxForm? \n  &form=`Form.callbackModal.Tpl`\n  &hooks=`email,FormItSaveForm`\n  &formName=`Заявка с сайта Двероконгрупп`\n  &allowFiles=`0`\n    \n  &emailSubject=`Заявка с сайта Двероконгрупп`\n  &emailTo=`[[++lp_email_notyfy]]`\n  &emailFrom=`[[++lp_email_from]]`\n  &emailFromName=`[[++site_name]]`\n  &emailTpl=`Form.email.Tpl`\n  \n  &validate=`phone:required,works_email:blank`\n  &validationErrorMessage=`В форме содержатся ошибки!`\n  &successMessage=`Сообщение успешно отправлено`\n  \n  &frontend_js=`` \n  &frontend_css=``\n]]', 0, 'a:0:{}', 0, ''),
(31, 1, 0, 'Form.callbackModal.Tpl', '', 0, 5, 0, '<div id=\"callback\" uk-modal>\n  <form class=\"uk-modal-dialog uk-margin-auto-vertical ajax_form\" method=\"post\" enctype=\"multipart/form-data\">\n    <button class=\"uk-modal-close-default\" type=\"button\" uk-close></button>\n    <div class=\"uk-modal-header uk-text-center\">\n      <p class=\"uk-h2 uk-text-uppercase uk-margin-remove\">Заказать звонок</p>\n    </div>\n    <div class=\"uk-modal-body uk-form-horizontal\">\n      <div class=\"uk-hidden\">\n        <input type=\"email\" id=\"af_works_email\" name=\"works_email\" value=\"[[+fi.works_email]]\">\n        [[!cityselect? &frontend_css=`0` &frontend_js=`0` &tpl=`tpl.CitySelect`]]\n		  </div>\n      <div class=\"uk-grid-small uk-grid\" uk-grid>\n        <div class=\"uk-width-1-1 uk-width-1-2@s\">\n          <div class=\"uk-inline uk-width-1-1\">\n            <span class=\"uk-form-icon uk-form-icon-flip\" uk-icon=\"icon: user\"></span>\n            <input class=\"uk-input uk-width-1-1\" type=\"text\" placeholder=\"Ваше Имя\" name=\"name\" value=\"[[+name]]\">\n          </div>\n        </div>\n        <div class=\"uk-width-1-1 uk-width-1-2@s\">\n          <div class=\"uk-inline uk-width-1-1\">\n            <span class=\"uk-form-icon uk-form-icon-flip\" uk-icon=\"icon: phone\"></span>\n            <input class=\"uk-input phone uk-width-1-1\" type=\"text\" placeholder=\"Ваш номер телефона\" name=\"phone\" value=\"[[+phone]]\">\n          </div>\n        </div>\n      </div>\n    </div>\n    <div class=\"uk-modal-footer uk-text-center\">\n      <button class=\"uk-button uk-button-danger\">Заказать</button>\n    </div>\n  </form>\n</div>', 0, 'a:0:{}', 0, ''),
(32, 1, 0, 'Form.Inline', '', 0, 5, 0, '[[!AjaxForm? \n  &form=`Form.Inline.Tpl`\n  &hooks=`email,FormItSaveForm`\n  &formName=`Заявка с сайта [[++site_name]]`\n  &allowFiles=`0`\n    \n  &emailSubject=`Заявка с сайта [[++site_name]]`\n  &emailTo=`[[++lp_email_notyfy]]`\n  &emailFrom=`[[++lp_email_from]]`\n  &emailFromName=`[[++site_name]]`\n  &emailTpl=`Form.email.Tpl`\n  \n  &validate=`phone:required,works_email:blank`\n  &validationErrorMessage=`В форме содержатся ошибки!`\n  &successMessage=`Сообщение успешно отправлено`\n  \n  &frontend_js=`` \n  &frontend_css=``\n]]', 0, 'a:0:{}', 0, ''),
(33, 1, 0, 'Form.Inline.Tpl', '[[+ms2g.0.xlarge]]', 0, 5, 0, '<section class=\"uk-section uk-section-secondary uk-light js-lozad uk-background-cover\" data-background-image=\"/tpl/images/form.jpg\" uk-parallax=\"bgy: -200\">\n  <div class=\"uk-container\">\n    <p class=\"uk-h1 uk-text-center\"><span class=\"uk-text-danger\">Отправить заявку</span> на расчет</p>\n    <p class=\"uk-text-center\">Рассчитаем цены по Вашим размерам за 15 минут</p>\n    <form class=\"uk-width-1-1 uk-width-large@m uk-margin-auto ajax_form\" method=\"post\" enctype=\"multipart/form-data\">\n      <div class=\"uk-hidden\">\n        <input type=\"email\" id=\"af_works_email\" name=\"works_email\" value=\"[[+fi.works_email]]\">\n        [[!cityselect? &frontend_css=`0` &frontend_js=`0` &tpl=`tpl.CitySelect`]]\n		  </div>\n      <div class=\"inline-form\">\n        <div class=\"uk-grid-collapse\" uk-grid>\n          <div class=\"uk-inline uk-width-expand\">\n            <span class=\"uk-form-icon\" uk-icon=\"icon: phone\"></span>\n            <input class=\"uk-width-1-1 inline-form-input uk-input phone\" placeholder=\"Номер телефона\" value=\"[[+fi.phone]]\" name=\"phone\">\n          </div>\n          <div class=\"uk-width-auto\">\n            <button class=\"uk-button uk-button-danger\"><span class=\"uk-visible@m\">Заказать расчет</span>\n              <span uk-icon=\"receiver\" class=\"uk-hidden@m\"></span></button>\n          </div>\n        </div>\n      </div>\n    </form>\n  </div>\n</section>', 0, 'a:0:{}', 0, ''),
(37, 0, 0, 'Home.Header', '', 0, 31, 0, '<header class=\"header-main uk-position-relative\">\n  {include \'Home.Header.Top\'}\n  {include \'Home.Header.Nav\'}\n  {include \'Home.Header.Content\'}\n</header>', 0, 'a:0:{}', 0, ''),
(44, 0, 0, 'Home.Video', '', 0, 31, 0, '{$_modx->runSnippet(\'ResVideoGallery\', [\n  \'resources\' => 1,\n  \'limit\' => 1,\n  \'ajax\' => 0,\n  \'tpl\' => \'VideoGalleryHome\',\n  \'tplRow\' => \'Home.Video.Row\',\n  \'tplEmbed\' => \'VideoGalleryEmbedTpl\'\n])}', 0, 'a:0:{}', 0, ''),
(45, 1, 0, 'Info.Content', '', 0, 47, 0, '<div class=\"uk-section uk-section-small uk-section-muted\" style=\"border-top: 1px solid #e9e9e9\">\n	<div class=\"uk-container\">\n		<div class=\"uk-grid uk-flex-center\" uk-grid>\n    	{include \'Info.Content.Sidebar\'}\n			<div class=\"uk-width-1-1 uk-width-expand@m\">\n			  {include \'Breadcrumb\'}\n			  <h1 class=\"uk-h1 uk-text-center\">{$_modx->resource.pagetitle}</h1>\n			  <hr class=\"title-divider\">\n			  \n			  {$_modx->getChunk(\'!Info.Content.Banner\')}\n			  	\n  			{$_modx->resource.content}\n  			{if $_modx->resource.showChildrens == 1}\n  			<p id=\"pod\" class=\"uk-h2 uk-text-center\">Узнать подробно</p>\n      	<div class=\"uk-width-1-1\">\n    			{$_modx->getChunk(\'!Info.Content.Childrens\')}\n  			</div>\n  			{/if}\n  			<p id=\"pod\" class=\"uk-h2 uk-text-center\">Смотрите видео</p>\n  			<div class=\"uk-grid uk-flex-middle\" uk-grid uk-lightbox=\"type: video; animation: scale; video-autoplay: true\">\n    		  {$_modx->runSnippet(\'ResVideoGallery\', [\n            \'resources\' => $_modx->resource.id,\n            \'limit\' => 0,\n            \'ajax\' => 0,\n            \'tpl\' => \'VideoGalleryHome\',\n            \'tplRow\' => \'VideoGalleryHome.Row\',\n            \'tplEmbed\' => \'VideoGalleryEmbedTpl\'\n          ])}\n    		</div>\n    		{if $_modx->resource.showGallery == 1}\n    		<p id=\"gal\" class=\"uk-h2 uk-text-center\">Фото выполненных работ</p>\n      	<div class=\"uk-margin-top\">\n    			{$_modx->getChunk(\'!Info.Content.Gallery\')}\n  			</div>\n  			{/if}\n  			{if $_modx->resource.underContent ?}\n  			<div class=\"uk-margin-top\">{$_modx->resource.underContent}</div>\n  			{/if}\n  			{if $_modx->resource.parent == 51}\n  			<div class=\"uk-margin-top\">\n  			  {$_modx->getChunk(\'!Info.Pagination.Publishedon\')}\n  			</div>\n  			{/if}\n    	</div>\n		</div>\n	</div>\n</div>', 0, 'a:0:{}', 0, ''),
(46, 0, 0, 'Info.Content.Childrens', '', 0, 47, 0, '<ul class=\"uk-grid-small uk-child-width-1-1 uk-child-width-1-2@s uk-child-width-1-2@m uk-child-width-1-3@l services\" uk-grid\n    uk-scrollspy=\"cls: uk-animation-fade uk-invisible; target: > li > .service; delay: 300; repeat: false\">\n  {$_modx->runSnippet(\'!ms2GalleryResources\', [\n    \'parents\' => $_modx->resource.id,\n    \'tpl\' => \'Home.Products.Row\',\n    \'limit\' => 0,\n    \'frontend_css\' => 0,\n    \'frontend_js\' => 0,\n    \'depth\' => 0,\n    \'showInactive\' => 0,\n    \'showHidden\' => 1,\n    \'includeThumbs\' => \'thumb\',\n    \'fastMode\' => 1,\n    \'sortby\' => \'menuindex\',\n    \'sortdir\' => \'ASC\'\n  ])}\n</ul>', 0, 'a:0:{}', 0, ''),
(47, 1, 0, 'Info.Content.Gallery', '[[+assetsUrl]]js/pdopage.min.js', 0, 47, 0, '<ul class=\"uk-margin-top uk-margin-bottom uk-grid uk-flex-center uk-grid-small uk-child-width-1-2 uk-child-width-1-3@s uk-child-width-1-4@m\" uk-scrollspy=\"target: > li > div; cls:uk-animation-fade; delay: 100; repeat: false\" uk-grid uk-scrollspy=\"target: > .masonry-item; cls:uk-animation-slide-bottom-small; delay: 100\" uk-lightbox=\"animation: scale\">\n  {$_modx->runSnippet(\'!ms2Gallery\', [\n    \'parents\' => 0,\n    \'resources\' => $_modx->resource.id,\n    \'tpl\' => \'Info.Content.Gallery.row\',\n    \'limit\' => 0,\n    \'cache\' => 1,\n    \'frontend_css\' => 0,\n    \'frontend_js\' => 0,\n  ])}\n</ul>', 0, 'a:0:{}', 0, ''),
(48, 1, 0, 'Info.Content.Gallery.row', '', 0, 47, 0, '{if $files?}\n  {foreach $files as $file}\n  <li>\n    <div class=\"uk-inline-clip uk-transition-toggle masonry-item uk-border-rounded\">\n    	<img src=\"{$file[\'thumb\']}\" alt=\"{$_modx->resource.pagetitle} - {$file[\'name\']}\" title=\"{$_modx->resource.pagetitle} - {$file[\'name\']}\" class=\"uk-transition-scale-up uk-transition-opaque\">\n    	<div class=\"uk-transition-fade uk-position-cover uk-position-small uk-overlay uk-overlay-primary uk-flex uk-flex-center uk-flex-middle uk-border-rounded\">\n    		 <span class=\"uk-transition-fade\" uk-icon=\"icon: plus; ratio: 2\"></span>\n    	</div>\n    	<a class=\"uk-position-cover\" href=\"{$file[\'large\']}\"></a>\n    </div>\n	</li>\n  {/foreach}\n{/if}', 0, 'a:0:{}', 0, ''),
(49, 0, 0, 'Info.Header', '', 0, 47, 0, '<header class=\"header-main uk-position-relative\">\n  {include \'Home.Header.Top\'}\n  {include \'Home.Header.Nav\'}\n</header>', 0, 'a:0:{}', 0, ''),
(50, 1, 0, 'Info.Pagination.Menuindex', '', 0, 47, 0, '{if $_modx->resource.isfolder != 1}\n\n{$_modx->runSnippet(\'!pdoNeighbors\', [\n  \'id\' => $_modx->resource.id,\n  \'tplUp\' => \'@INLINE \',\n  \'tplPrev\' => \'@INLINE \n    <li>\n      <a href=\"{{+link}}\" title=\"{{+pagetitle}}\" uk-tooltip=\"pos: top-left; animation: uk-animation-slide-right-small\"><span class=\"uk-margin-small-right\" uk-pagination-previous></span> Назад</a>\n    </li>\',\n  \'tplNext\' => \'@INLINE \n    <li class=\"uk-margin-auto-left\">\n      <a href=\"{{+link}}\" title=\"{{+pagetitle}}\" uk-tooltip=\"pos: top-right; animation: uk-animation-slide-left-small\">Вперед <span class=\"uk-margin-small-left\" uk-pagination-next></span></a>\n    </li>\',\n  \'tplWrapper\' => \'@INLINE \n    <div class=\"uk-card uk-card-body uk-background-default uk-border-rounded uk-box-shadow-small\">\n      \n      <ul class=\"uk-pagination\">{{+prev}} {{+up}} {{+next}}</ul>\n    </div>\',\n  \'fastMode\' => 1,\n  \'sortby\' => \'menuindex\',\n  \'sortdir\' => \'ASC\',\n  \'hideContainers\' => 1,\n  \'loop\' => 0,\n])}\n\n{/if}', 0, 'a:0:{}', 0, ''),
(51, 1, 0, 'Info.Pagination.Publishedon', '', 0, 47, 0, '{if $_modx->resource.isfolder != 1}\n{$_modx->runSnippet(\'!pdoNeighbors\', [\n  \'id\' => $_modx->resource.id,\n  \'tplUp\' => \'@INLINE \',\n  \'tplPrev\' => \'@INLINE \n    <li>\n      <a href=\"{{+link}}\" title=\"{{+pagetitle}}\" uk-tooltip=\"pos: top-left; animation: uk-animation-slide-right-small\"><span class=\"uk-margin-small-right\" uk-pagination-previous></span> Назад</a>\n    </li>\',\n  \'tplNext\' => \'@INLINE \n    <li class=\"uk-margin-auto-left\">\n      <a href=\"{{+link}}\" title=\"{{+pagetitle}}\" uk-tooltip=\"pos: top-right; animation: uk-animation-slide-left-small\">Вперед <span class=\"uk-margin-small-left\" uk-pagination-next></span></a>\n    </li>\',\n  \'tplWrapper\' => \'@INLINE \n    <div class=\"uk-margin-large\">\n      <ul class=\"uk-pagination\">{{+prev}} {{+up}} {{+next}}</ul>\n    </div>\',\n  \'fastMode\' => 1,\n  \'sortby\' => \'publishedon\',\n  \'sortdir\' => \'DESC\',\n  \'hideContainers\' => 1,\n  \'loop\' => 0,\n])}\n{/if}', 0, 'a:0:{}', 0, ''),
(52, 1, 0, 'Info.Sidebar.Section', '', 0, 25, 0, '<div class=\"uk-width-1-1 uk-width-1-2@s uk-width-1-3@m uk-width-1-1@l\">\n	<div class=\"uk-card uk-card-small uk-card-default uk-border-rounded\">\n		<div class=\"uk-card-header\">\n			<p class=\"uk-card-title\">Выберите раздел</p>\n		</div>\n		<div class=\"uk-card-body uk-background-muted\">\n		  {if $_modx->resource.parent == 0 }\n		    {$_modx->runSnippet(\'!pdoMenu\', [\n          \'parents\' => $_modx->resource.id,\n          \'fastMode\' => 1,\n          \'level\' => 1,\n          \'cache\' => 0,\n          \'showHidden\' => 0,\n          \'where\' => \'\',\n          \'countChildren\' => 0,\n          \'cache\' => 1,\n          \'hereClass\' => \'uk-active\',\n          \'tplOuter\' => \'@INLINE \n            <ul class=\"uk-nav-default uk-nav-default\" uk-nav>\n              {{+wrapper}}\n            </ul>\',\n          \'tpl\' => \'@INLINE \n            <li {{+classes}}><a href=\"{{+link}}\" {{+attributes`}}`>{{+menutitle}} </a></li>\'\n        ])}\n  		{else}\n  		  {$_modx->runSnippet(\'!pdoMenu\', [\n          \'parents\' => $_modx->resource.parent,\n          \'fastMode\' => 1,\n          \'level\' => 1,\n          \'cache\' => 1,\n          \'showHidden\' => 0,\n          \'where\' => \'\',\n          \'countChildren\' => 0,\n          \'cache\' => 1,\n          \'hereClass\' => \'uk-active\',\n          \'tplOuter\' => \'@INLINE \n            <ul class=\"uk-nav-default uk-nav-default\" uk-nav>\n              {{+wrapper}}\n            </ul>\',\n          \'tpl\' => \'@INLINE \n            <li {{+classes}}><a href=\"{{+link}}\" {{+attributes`}}`>{{+menutitle}} </a></li>\'\n        ])}\n  		{/if}\n		</div>\n	</div>\n</div>', 0, 'a:0:{}', 0, ''),
(53, 1, 0, 'Info.SubpagePagin', '', 0, 25, 0, '<div id=\"listart\">\n  <div class=\"uk-grid uk-grid-small\" uk-grid>\n    {$_modx->runSnippet(\'!pdoPage\', [\n      \'parents\' => $_modx->resource.id,\n      \'limit\' => 4,\n      \'depth\' => 2,\n      \'pageLimit\' => 1,\n      \'cache\' => 0,\n      \'cacheAnonymous\' => 0,\n      \'ajax\' => 1,\n      \'ajaxMode\' => \'default\',\n      \'ajaxElemWrapper\' => \'#listart\',\n      \'ajaxElemRows\' => \'#listart .uk-grid\',\n      \'ajaxElemPagination\' => \'#listart .uk-pagination\',\n      \'ajaxElemLink\' => \'#listart .uk-pagination a\',\n      \'ajaxElemMore\' => \'#listart .show-more\',\n      \'ajaxTplMore\' => \'@INLINE <div class=\"uk-margin uk-text-center\"><button class=\"uk-button uk-button-default show-more\">[[%pdopage_more]]</button></div>\',\n      \'ajaxHistory\' => 1,\n      \'frontend_js\' => 0,\n      \'frontend_css\' => 0,\n      \'fastMode\' => 0,\n      \'showHidden\' => 1,\n      \'hideContainers\' => 1,\n      \'showLog\' => 0,\n      \'includeContent\' => 0,\n      \'sortby\' => \'publishedon\',\n      \'sortdir\' => \'DESC\',\n      \'tpl\' => \'Info.SubpagePagin.row\',\n      \'tplPage\' => \'@INLINE <li><a href=\"{{+href}}\">{{+pageNo}}</a></li>\',\n      \'tplPageWrapper\' => \'@INLINE <ul class=\"uk-pagination uk-flex-center uk-margin-top\" uk-margin>{{+prev}}{{+pages}}{{+next}}</ul>\',\n      \'tplPageActive\' => \'@INLINE <li class=\"uk-active\"><span>{{+pageNo}}</span></li>\',\n      \'tplPageFirst\' => \'\',\n      \'tplPageLast\' => \'\',\n      \'tplPagePrev\' => \'@INLINE <li><a href=\"{{+href}}\"><span uk-pagination-previous></span></a></li>\',\n      \'tplPageNext\' => \'@INLINE <li><a href=\"{{+href}}\"><span uk-pagination-next></span></a></li>\',\n      \'tplPageSkip\' => \'\',\n      \'tplPageFirstEmpty\' => \'\',\n      \'tplPageLastEmpty\' => \'\',\n      \'tplPagePrevEmpty\' => \'\',\n      \'tplPageNextEmpty\' => \'\',\n      \'element\' => \'getTickets\',\n      \'loadModels\' => \'ms2gallery\',\n      \'class\' => \'Ticket\',\n      \'leftJoin\' => \'{\n        \"medium\" : {\n          \"class\" : \"msResourceFile\",\n            \"alias\" : \"medium\",\n            \"on\" : \"medium.resource_id = Ticket.id AND medium.path LIKE \\\'%/medium/\\\' AND medium.rank=0\"\n          }\n      }\',\n      \'select\' => \'{ \"medium\" : \"medium.url as medium\" }\',\n    ])}\n  </div>\n  {$_modx->getPlaceholder(\'page.nav\')}\n</div>', 0, 'a:0:{}', 0, ''),
(54, 1, 0, 'Info.SubpagePagin.row', '', 0, 25, 0, '<div class=\"uk-width-1-1\">\n  <div class=\"uk-card uk-card-small uk-card-hover uk-card-default uk-transition-toggle\" data-id=\"{$id}\">\n    <div class=\"uk-card-media-top uk-overflow-hidden uk-inline-clip\">\n      <img src=\"{$medium}\" alt=\"{$pagetitle}\" class=\"uk-transition-scale-up uk-transition-opaque\">\n      <div class=\"uk-overlay uk-position-bottom uk-dark uk-overlay-default uk-position-small\">\n        <h3 class=\"uk-card-title\">{$pagetitle}</h3>\n      </div>\n      <a href=\"{$uri}\" title=\"{$pagetitle}\" class=\"uk-transition-fade uk-position-cover uk-position-small uk-overlay uk-flex uk-flex-center uk-flex-middle uk-link-reset\"></a>\n      <div class=\"uk-card-badge uk-label uk-label-danger\"><span class=\"uk-margin-small-right\" uk-icon=\"icon: calendar; ratio: 0.9\"></span> <time datetime=\"{$_modx->resource.createdon | date_format : \'%Y-%m-%dT%T\'}\"> {$date_ago}</div>\n    </div>\n    <div class=\"uk-card-body\">\n      <ul class=\"uk-text-meta uk-subnav uk-subnav-divider\" uk-margin>\n        <li><span class=\"uk-margin-small-right\" uk-icon=\"icon: album; ratio: 0.9\"></span> {$_pls[\'section.pagetitle\']}</li>\n        {if $fullname ?}\n          <li class=\"uk-visible@m\"><span class=\"uk-margin-small-right\" uk-icon=\"icon: user; ratio: 0.9\"></span> {$fullname}</li>\n        {/if}\n        {if $views ?}\n          <li class=\"uk-visible@m\"><span class=\"uk-margin-small-right\" uk-icon=\"icon: users; ratio: 0.9\"></span> {$views}</li>\n        {/if}\n        {if $comments ?}\n          <li><span class=\"uk-margin-small-right\" uk-icon=\"icon: comments; ratio: 0.9\"></span> {$comments} {if $new_comments ? }+{$new_comments}{/if}</li>\n        {/if}\n        <li class=\"uk-visible@m\"><span class=\"uk-margin-small-right\" uk-icon=\"icon: happy; ratio: 0.9\"></span> <span class=\"ticket-rating{$active}{$inactive}\">{$rating_total}</span></li>\n      </ul>\n    </div>\n    <div class=\"uk-card-footer\">\n      <a href=\"{$uri}\" class=\"uk-button uk-button-text\" title=\"{$pagetitle}\">подробнее</a>\n    </div>\n  </div>\n</div>', 0, 'a:0:{}', 0, ''),
(55, 1, 0, 'Meta', '', 0, 3, 0, '<meta charset=\"UTF-8\">\n<title>{if $_modx->resource.longtitle ?}{$_modx->resource.longtitle | notags | esc}{else}{$_modx->resource.pagetitle | notags | esc}{/if} | {$_modx->config.site_name | notags | esc}</title>\n<meta name=\"description\" content=\"{if $_modx->resource.description ?}{$_modx->resource.description | notags | esc}{else}{$_modx->resource.longtitle | notags | esc}{/if}\">\n<meta name=\"viewport\" content=\"initial-scale=1.0, width=device-width\">\n<meta name=\"yandex-verification\" content=\"29d40a8dce80cf90\" />\n<meta name=\"yandex-verification\" content=\"bf43af3683fa8d91\" />\n{if $_modx->config.lp_noindex == 1 }\n<meta name=\"robots\" content=\"noindex\">\n<meta name=\"robots\" content=\"nofollow\">\n<meta name=\"robots\" content=\"none\">\n<meta name=\"robots\" content=\"noarchive\">\n<meta name=\"robots\" content=\"noyaca\">\n{/if}\n<meta name=\"format-detection\" content=\"telephone=no\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<meta name=\"HandheldFriendly\" content=\"true\">\n<meta property=\"og:url\" content=\"{$_modx->makeUrl($_modx->resource.id,\'\',\'\',\'full\')}\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:title\" content=\"{if $_modx->resource.longtitle ?}{$_modx->resource.longtitle | notags | esc}{else}{$_modx->resource.pagetitle | notags | esc}{/if}\">\n<meta property=\"og:description\" content=\"{if $_modx->resource.description ?}{$_modx->resource.description | notags | esc}{else}{$_modx->resource.longtitle | notags | esc}{/if}\">\n<meta property=\"og:image\" content=\"{$_modx->config.site_url}tpl/icons/android-chrome-512x512.png\">\n<meta name=\"twitter:card\" content=\"summary\">\n<meta name=\"twitter:title\" content=\"{if $_modx->resource.longtitle ?}{$_modx->resource.longtitle | notags | esc}{else}{$_modx->resource.pagetitle | notags | esc}{/if}\">\n<meta name=\"twitter:description\" content=\"{if $_modx->resource.description ?}{$_modx->resource.description | notags | esc}{else}{$_modx->resource.longtitle | notags | esc}{/if}\">\n<meta name=\"twitter:image\" content=\"{$_modx->config.site_url}tpl/icons/android-chrome-512x512.png\">\n<meta property=\"business:contact_data:street_address\" content=\"{$_modx->config.lp_address_street}\">\n<meta property=\"business:contact_data:locality\" content=\"{$_modx->config.lp_address_city}\">\n<meta property=\"business:contact_data:postal_code\" content=\"197343\">\n<meta property=\"business:contact_data:country_name\" content=\"Россия\">\n<meta name=\"author\" content=\"{$_modx->config.site_name | esc}\">\n<meta name=\"application-name\" content=\"{$_modx->config.site_name | notags | esc}\">\n<meta name=\"msapplication-TileColor\" content=\"#D04943\">\n<meta name=\"msapplication-TileImage\" content=\"{$_modx->config.site_name | notags | esc}\">\n<meta name=\"msapplication-square70x70logo\" content=\"{$_modx->config.site_url}tpl/icons/mstile-70x70.png\">\n<meta name=\"msapplication-square150x150logo\" content=\"{$_modx->config.site_url}tpl/icons/mstile-150x150.png\">\n<meta name=\"msapplication-wide310x150logo\" content=\"{$_modx->config.site_url}tpl/icons/mstile-310x150.png\">\n<meta name=\"msapplication-square310x310logo\" content=\"{$_modx->config.site_url}tpl/icons/mstile-310x310.png\">\n<meta name=\"apple-touch-fullscreen\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-title\" content=\"{if $_modx->resource.longtitle ?}{$_modx->resource.longtitle | notags | esc}{else}{$_modx->resource.pagetitle | notags | esc}{/if} | {$_modx->config.site_name | notags | esc}\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<link rel=\"mask-icon\" href=\"{$_modx->config.site_url}tpl/icons/safari-pinned-tab.svg\" color=\"#00а0ff\">\n<link rel=\"apple-touch-icon\" sizes=\"57x57\" href=\"{$_modx->config.site_url}tpl/icons/apple-touch-icon-57x57.png\">\n<link rel=\"apple-touch-icon\" sizes=\"60x60\" href=\"{$_modx->config.site_url}tpl/icons/apple-touch-icon-60x60.png\">\n<link rel=\"apple-touch-icon\" sizes=\"72x72\" href=\"{$_modx->config.site_url}tpl/icons/apple-touch-icon-72x72.png\">\n<link rel=\"apple-touch-icon\" sizes=\"76x76\" href=\"{$_modx->config.site_url}tpl/icons/apple-touch-icon-76x76.png\">\n<link rel=\"apple-touch-icon\" sizes=\"114x114\" href=\"{$_modx->config.site_url}tpl/icons/apple-touch-icon-114x114.png\">\n<link rel=\"apple-touch-icon\" sizes=\"120x120\" href=\"{$_modx->config.site_url}tpl/icons/apple-touch-icon-120x120.png\">\n<link rel=\"apple-touch-icon\" sizes=\"144x144\" href=\"{$_modx->config.site_url}tpl/icons/apple-touch-icon-144x144.png\">\n<link rel=\"apple-touch-icon\" sizes=\"152x152\" href=\"{$_modx->config.site_url}tpl/icons/apple-touch-icon-152x152.png\">\n<link rel=\"apple-touch-icon\" sizes=\"180x180\" href=\"{$_modx->config.site_url}tpl/icons/apple-touch-icon-180x180.png\">\n<link rel=\"image_src\" href=\"{$_modx->config.site_url}tpl/icons/apple-touch-icon-180x180.png\">\n<link rel=\"shortcut icon\" type=\"image/x-icon\" href=\"{$_modx->config.site_url}tpl/icons/favicon.ico\">\n<link rel=\"icon\" href=\"{$_modx->config.site_url}tpl/icons/favicon.ico\">\n<link rel=\"manifest\" href=\"{$_modx->config.site_url}tpl/icons/manifest.json\">\n<base href=\"{$_modx->config.site_url}\"> \n{ignore}<style>.preloader { position: fixed; top: 0; bottom: 0; width: 100%; background: #38373d url(tpl/img/loader.svg) 50% 50% no-repeat; background-size: 58px 48px; z-index: 10000000000; animation: loader .9s ease-in-out infinite; transform-origin: center}\n@keyframes loader {\n  0% {transform: scale(1) rotate(0deg)}\n  25% {transform: scale(1.6) rotate(-10deg)}\n  50% {transform: scale(1) rotate(0deg)}\n  75% {transform: scale(1.6) rotate(10deg)}\n  100% {transform: scale(1) rotate(0deg)}\n}</style>{/ignore}', 0, 'a:0:{}', 0, ''),
(56, 1, 0, 'MiniFix.main', '', 0, 9, 0, '[[MinifyX?\n  &jsSources=`\n    [[++base_url]]tpl/js/libs.main.min.js,\n    [[++assets_url]]components/pdotools/js/pdopage.js,\n    [[++assets_url]]components/ms2gallery/js/web/default.js,\n    [[++assets_url]]components/ajaxform/js/lib/jquery.form.min.js,\n    [[++assets_url]]components/ajaxform/js/default-custom.js,\n    [[++assets_url]]components/cityselect/js/web/default.js,\n    [[++base_url]]tpl/js/setting__core.js,\n    [[++base_url]]tpl/js/setting__main.js\n  `\n  &cssSources=`\n    [[++base_url]]tpl/css/custom.css\n  `\n  &minifyJs=`1`\n  &minifyCss=`1`\n]]', 0, 'a:0:{}', 0, ''),
(60, 0, 0, 'Nav.top', '', 0, 3, 0, '{$_modx->runSnippet(\'pdoMenu\', [\n  \'parents\' => 0,\n  \'resources\' => \'-1\',\n  \'fastMode\' => 1,\n  \'level\' => 0,\n  \'cache\' => 1,\n  \'showHidden\' => 0,\n	\'countChildren\' => 0,\n  \'hereClass\' => \'uk-active\',\n	\'lastClass\' => \'0\',\n	\'firstClass\' => \'0\',\n  \'tplOuter\' => \'@INLINE {{+wrapper}}\',\n  \'tpl\' => \'@INLINE <li {{+classes}} class=\"uk-visible@l\"><a href=\"{{+link}}\" {{+attributes}}>{{+menutitle}}</a></li>\'\n])}', 0, 'a:0:{}', 0, ''),
(61, 1, 0, 'offcanvas', '', 0, 3, 0, '<div id=\"side-menu\" class=\"uk-modal-full\" uk-modal>\n  <div class=\"uk-modal-dialog\">\n    <button class=\"uk-modal-close-full uk-close-large\" type=\"button\" uk-close></button>\n    <div class=\"uk-height-viewport uk-flex uk-flex-center uk-flex-middle\">\n      <div>\n        <ul class=\"uk-nav-primary font-secondary uk-nav-default\" uk-nav>\n          {$_modx->runSnippet(\'pdoMenu\', [\n            \'parents\' => 0,\n            \'resources\' => \'\',\n            \'fastMode\' => 1,\n            \'level\' => 1,\n            \'cache\' => 1,\n            \'showHidden\' => 0,\n          	\'countChildren\' => 0,\n            \'hereClass\' => \'uk-active\',\n            \'parentClass\' => \'uk-parent\',\n            \'lastClass\' => \'0\',\n          	\'firstClass\' => \'0\',\n            \'tplOuter\' => \'@INLINE {{+wrapper}}\',\n            \'tpl\' => \'@INLINE <li {{+classes}} ><a href=\"{{+link}}\" {{+attributes}} >{{+menutitle}}</a></li>\',\n          	\'tplParentRow\' => \'@INLINE <li {{+classes}} ><a href=\"{{+link}}\" {{+attributes}} >{{+menutitle}}</a>\n          	  {{+wrapper}}</li>\',\n          	\'tplParentRowHere\' => \'\',\n          	\'tplParentRowActive\' => \'\',\n          	\'tplInner\' => \'@INLINE <ul class=\"uk-nav-sub\" >{{+wrapper}}</ul>\',\n          	\'tplInnerRow\' => \'@INLINE <li {{+classes}} ><a href=\"{{+link}}\" {{+attributes}} >{{+menutitle}}</a></li>\',\n          ])}\n        </ul>\n      </div>\n    </div>\n  </div>\n</div>', 0, 'a:0:{}', 0, ''),
(82, 0, 0, 'SiteMap', '', 0, 32, 0, '\n\n{$_modx->runSnippet(\'!pdoMenu\', [\n  \'parents\' => 0,\n  \'resources\' => \'\',\n  \'level\' => 10,\n  \'outerClass\' => \'uk-nav\',\n  \'where\' => [\'searchable\' => 1],\n  \'parentClass\' => \'uk-parent\',\n  \'innerClass\' => \'innerClass\',\n  \'tplOuter\' => \'@INLINE <ul class=\"uk-list uk-list uk-list-divider\">[[+wrapper]]</ul>\',\n  \'tpl\' => \'@INLINE <li[[+classes]]><a href=\"[[+link]]\" class=\"uk-button-text uk-text-uppercase\" [[+attributes]]>[[+menutitle]]</a>[[+wrapper]]</li>\'\n  \'tplInner\' => \'@INLINE <ul class=\"uk-list uk-margin-top uk-margin-bottom uk-margin-left\">[[+wrapper]]</ul>\',\n  \'tplInnerRow\' => \'@INLINE <li[[+classes]]><a href=\"[[+link]]\" class=\"uk-text-muted uk-button-text\" [[+attributes]]>[[+menutitle]]</a>[[+wrapper]]</li>\',\n  \'cache\' => 0,\n  \'showHidden\' => 1,\n  \'fastMode\' => 1,\n  \'showLog\' => 0,\n])}', 0, 'a:0:{}', 0, ''),
(83, 1, 0, 'terms', '', 0, 3, 0, '<div id=\"terms\" class=\"uk-modal-container\"  uk-modal=\"stack: true\">\n  <div class=\"uk-modal-dialog uk-background-muted\">\n    <button class=\"uk-modal-close-default\" type=\"button\" uk-close></button>\n    <div class=\"uk-modal-header\">\n      <h2 class=\"uk-modal-title uk-text-primary uk-margin-remove\">{$_modx->config.lp_terms | resource : \'pagetitle\'} </h2>\n      <p class=\"uk-clearfix text-light uk-text-primary uk-margin-small-top\">{$_modx->config.lp_address_city}<span class=\"uk-float-right\">{33 | resource : \'publishedon\' | date_format : \'%d-%m-%Y\'}</span></p>\n    </div>\n    <div class=\"uk-modal-body\" id=\"terms-content\" uk-overflow-auto></div>\n  </div>\n  <script>$(document).ready(function () { $(\'#terms\').on(\'show\', function () { $( \"#terms-content\" ).load( \"{33 | url}\" )});});</script>\n</div>', 0, 'a:0:{}', 0, ''),
