(88, 0, 0, 'VideoGalleryHome.Row', '', 0, 33, 0, '<div>\n  <div class=\"uk-position-relative js-lozad\" data-background-image=\"[[+thumb]]\">\n    <canvas width=\"1280\" height=\"450\"></canvas>\n    <a href=\"[[+url]]\" class=\"uk-position-cover uk-overlay uk-overlay-primary uk-light\" title=\"[[+title]]\">\n      <span class=\"uk-position-center\">\n        <span uk-icon=\"icon: play-circle; ratio: 3\"></span>\n      </span> </a>\n  </div>\n</div>', 0, 'a:0:{}', 0, ''),
(89, 0, 0, 'YandexMap', '', 0, 3, 0, '{ignore}\n<script>\n$(document).ready(function () { \n   $.getScript(\'https://api-maps.yandex.ru/2.1/?lang=ru-RU\').done(function (script, textStatus) {\n    ymaps.ready(init);\n      function init () { \n        var myMap = new ymaps.Map(\'map\', { \n            center: [ [[*map]] ],\n            zoom: 15,\n            controls: [\'zoomControl\',  \'fullscreenControl\'],\n          }),\n          objectManager = new ymaps.ObjectManager({\n            clusterize: true,\n            checkZoomRange:true,\n            gridSize: 48\n          });\n        myMap.behaviors.disable(\'scrollZoom\');\n        objectManager.objects.options.set(\'preset\', \'islands#redDotIcon\');\n        objectManager.clusters.options.set(\'preset\', \'islands#redClusterIcons\');\n        myMap.geoObjects.add(objectManager);\n        objectManager.add({ \"type\": \"FeatureCollection\", \"features\": \n          [{ \"type\": \"FeatureCollection\", \"features\": [ \n{/ignore}\n        {\n        	\'type\': \'Feature\',\n        	\'id\': 1,\n        	\'geometry\': { \'type\': \'Point\', \'coordinates\': [ [[*map]] ]},\n        	\'properties\': { \'balloonContent\': \'<b>[[++site_name]]</b>\',\'clusterCaption\': \'[[++site_name]]\',\'hintContent\':    \'[[++site_name]]\'}\n        }\n        \n{ignore}\n        ]}\n      ]});\n    }\n  });\n});\n</script>\n{/ignore}\n <div class=\"uk-card uk-card-default uk-border-rounded\">\n  <div class=\"uk-card-media-top\">\n    <div id=\"map\" class=\"uk-card\" style=\"height:340px\"></div>\n  </div>\n  <div class=\"uk-card-body\">\n    <p class=\"uk-card-title\">{$_modx->config.site_name}</p>\n    <ul class=\"uk-list uk-text-large\">\n      {if $_modx->config.lp_address_street ?}<li><span uk-icon=\"icon: location; ratio: 1.3\" class=\"uk-margin-small-right\"></span> {$_modx->config.lp_address_city}, {$_modx->config.lp_address_street}</li> {/if}\n      {if $_modx->config.lp_phone ?}<li><span uk-icon=\"icon: phone; ratio: 1.3\" class=\"uk-margin-small-right\"></span><a class=\"uk-button-text uk-link-reset\" href=\"tel:{$_modx->config.lp_phone | replace : \"(\" : \"\" | replace : \")\" : \"\" | replace : \"-\" : \"\" | replace : \" \" : \"\"}\"> {$_modx->config.lp_phone} {$_modx->config.lp_phone_descr}</a></li> {/if}\n			{if $_modx->config.lp_phone_2 ?}<li><span uk-icon=\"icon: phone; ratio: 1.3\" class=\"uk-margin-small-right\"></span><a class=\"uk-button-text uk-link-reset\" href=\"tel:{$_modx->config.lp_phone_2 | replace : \"(\" : \"\" | replace : \")\" : \"\" | replace : \"-\" : \"\" | replace : \" \" : \"\"}\"> {$_modx->config.lp_phone_2} {$_modx->config.lp_phone_2_descr}</a></li> {/if}\n			{if $_modx->config.lp_email ?}<li><span uk-icon=\"icon: mail; ratio: 1.3\" class=\"uk-margin-small-right\"></span>\n							<a href=\"mailto:{$_modx->config.lp_email}\" class=\"uk-button-text uk-link-reset\"> {$_modx->config.lp_email}</a></li> {/if}\n      <li>{if $_modx->config.lp_instagram ?} <a uk-icon=\"icon: instagram; ratio: 2\" href=\"{$_modx->config.lp_instagram}\" class=\"uk-margin-small-right\"></a> {/if}\n  		{if $_modx->config.lp_twitter ?} <a uk-icon=\"icon: twitter; ratio: 2\" href=\"{$_modx->config.lp_twitter}\" class=\"uk-margin-small-right\"></a> {/if}\n  		{if $_modx->config.lp_youtube ?} <a uk-icon=\"icon: youtube; ratio: 2\" href=\"{$_modx->config.lp_youtube}\" class=\"uk-margin-small-right\"></a> {/if}</li>\n    </ul>\n  </div>\n</div>\n', 0, 'a:0:{}', 0, ''),
