(93, 1, 0, 'tpl.ms2Gallery', '', 0, 40, 0, '<div class=\"ms2Gallery\">\n    {if $files?}\n        <div class=\"fotorama\"\n             data-nav=\"thumbs\"\n             data-thumbheight=\"45\"\n             data-allowfullscreen=\"true\"\n             data-swipe=\"true\"\n             data-autoplay=\"5000\">\n            {foreach $files as $file}\n                <a href=\"{$file[\'url\']}\" target=\"_blank\">\n                    <img src=\"{$file[\'small\']}\" alt=\"{$file[\'name\']}\" title=\"{$file[\'name\']}\">\n                </a>\n            {/foreach}\n        </div>\n    {else}\n        <img src=\"{(\'assets_url\' | option) ~ \'components/ms2gallery/img/web/ms2_medium.png\'}\" alt=\"\" title=\"\"/>\n    {/if}\n</div>', 0, NULL, 0, 'core/components/ms2gallery/elements/chunks/chunk.ms2gallery.tpl'),
(98, 4, 0, 'Home.TitleBlock', '', 0, 31, 0, '<section class=\"uk-section-secondary uk-background-fixed uk-background-cover\" style=\"background-image: url([[+ms2g.2.xlarge]])\">\n  <div class=\"uk-overlay-primary uk-section uk-section-large\">\n    <div class=\"uk-container\">\n      <div class=\"uk-grid uk-flex-center\" uk-grid>\n        <div class=\"uk-width-1-1 uk-width-3-4@l uk-text-center\">\n          <h1 class=\"uk-h1 uk-text-uppercase\">{$_modx->resource.title2}</h1>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>', 0, 'a:0:{}', 0, ''),
(102, 4, 0, 'Home.Folio', '', 0, 31, 0, '<section class=\"uk-section uk-section-large uk-section-default\">\n  <div class=\"uk-container\">\n    <div class=\"uk-flex-middle uk-flex-center\" uk-grid>\n      <div class=\"uk-width-1-1\"><h4 class=\"uk-h1\">Дома, построенные по технологии ВЕЛОКС</h4></div>\n      <div class=\"uk-width-1-1 uk-width-5-6@s\">\n        <div uk-slider=\"sets: true; clsActivated: uk-transition-active\">\n          <div class=\"uk-position-relative\">\n            <div class=\"uk-slider-container uk-light\">\n              <ul class=\"uk-slider-items uk-child-width-1-1 uk-child-width-1-2@m uk-child-width-1-3@l\">\n                {$_modx->runSnippet(\'!ms2GalleryResources\', [\n                  \'parents\' => 54,\n                  \'tpl\' => \'Home.Folio.Row\',\n                  \'limit\' => 0,\n                  \'frontend_css\' => 0,\n                  \'frontend_js\' => 0,\n                  \'showLog\' => 0,\n                  \'showInactive\' => 0,\n                  \'includeThumbs\' => \'thumb\',\n                  \'fastMode\' => 1,\n                  \'sortby\' => \'publishedon\',\n                  \'sortdir\' => \'DESC\'\n                ])}\n              </ul>\n            </div>\n            <div class=\"uk-hidden@s uk-light\">\n              <a class=\"uk-position-center-left uk-position-small slidenav-size\" href=\"#\" uk-slidenav-previous uk-slider-item=\"previous\"></a>\n              <a class=\"uk-position-center-right uk-position-small slidenav-size\" href=\"#\" uk-slidenav-next uk-slider-item=\"next\"></a>\n            </div>\n            <div class=\"uk-visible@s\">\n              <a class=\"uk-position-center-left-out uk-position-small slidenav-size\" href=\"#\" uk-slidenav-previous uk-slider-item=\"previous\"></a>\n              <a class=\"uk-position-center-right-out uk-position-small slidenav-size\" href=\"#\" uk-slidenav-next uk-slider-item=\"next\"></a>\n            </div>\n          </div>\n          <ul class=\"uk-slider-nav uk-dotnav uk-flex-center uk-margin\"></ul>\n        </div>\n      </div>\n      <div class=\"uk-width-1-1\"></div>\n      <div class=\"uk-width-1-1 uk-width-expand@l uk-text-large\">Вы можете посетить одну из наших строительных площадок, и посмотреть, как происходит строительство дома по технологии ВЕЛОКС</div>\n      <div class=\"uk-width-1-1 uk-width-auto@l\">\n        <button type=\"button\" class=\"uk-button uk-button-large uk-button-primary button-3d uk-text-uppercase\" uk-toggle=\"#callback\">Посетить строящийся объект</button>\n      </div>\n    </div>\n  </div>\n</section>', 0, 'a:0:{}', 0, ''),
(103, 0, 0, 'Home.Folio.Row', 'resource_id', 0, 31, 0, '<li>\n  <figure class=\"folioItem\">\n    <img src=\"{$thumb}\" alt=\"{$pagetitle}\">\n    <figcaption class=\"folioItem--panel uk-transition-slide-bottom\">\n      <a href=\"{$uri}\" class=\"folioItem--more\">подробнее <span uk-icon=\"chevron-right\" class=\"uk-icon\"></span></a>\n    </figcaption>\n  </figure>\n</li>', 0, 'a:0:{}', 0, ''),
(104, 0, 0, 'Home.Potentiality', '', 0, 31, 0, '<section class=\"uk-section uk-section-large uk-section-default\">\n    <div class=\"uk-container uk-container-large\">\n      <div class=\"uk-grid uk-flex-center\" uk-grid>\n        <div class=\"uk-width-1-1 uk-width-3-4@l uk-text-center\">\n          <p class=\"uk-h1 uk-text-uppercase\"><span>Наши возможности</span></p>\n          <hr class=\"uk-divider-small\">\n        </div>\n        <div class=\"uk-width-1-1 uk-width-3-4@l\">\n          <ul class=\"uk-grid-small uk-flex-center uk-grid uk-child-width-1-1 uk-child-width-1-2@m\" uk-height-match=\"target: .uk-card\" uk-grid>\n            {$_modx->runSnippet(\'getImageList\', [\n              \'tvname\' => \'Potentiality\',\n              \'limit\' => 0,\n              \'tpl\' => \'Home.Potentiality.Row\',\n              \'docid\' => $_modx->resource.id\n            ])}\n          </ul>\n        </div>\n      </div>\n    </div>\n  </section>', 0, 'a:0:{}', 0, ''),
(105, 0, 0, 'Home.Map', '\n\n', 0, 31, 0, '{ignore}\n<script>\n$(document).ready(function () { \n   $.getScript(\'https://api-maps.yandex.ru/2.1/?lang=ru-RU\').done(function (script, textStatus) {\n    ymaps.ready(init);\n      function init () { \n        var myMap = new ymaps.Map(\'map\', { \n            center: [ [[#9.map]] ],\n            zoom: 16,\n            controls: [\'zoomControl\'],\n        }),\n        objectManager = new ymaps.ObjectManager({\n          clusterize: true,\n          checkZoomRange:true,\n          gridSize: 48\n        });\n        myMap.behaviors.disable(\'scrollZoom\');\n        objectManager.objects.options.set(\'preset\', \'islands#redDotIcon\');\n        objectManager.clusters.options.set(\'preset\', \'islands#redClusterIcons\');\n        myMap.geoObjects.add(objectManager);\n        objectManager.add({ \"type\": \"FeatureCollection\", \"features\": [\n          { \"type\": \"Feature\", \n            \"id\": 1, \n            \"geometry\": { \n              \"type\": \"Point\", \n              \"coordinates\": [ [[#9.map]] ] \n            }\n          }\n        ]});\n    }\n  });\n});\n</script>\n{/ignore}\n<section class=\"uk-section\">\n  <div class=\"uk-container\">\n    <h2 class=\"uk-h1 uk-text-center\">Как к нам проехать</h2>\n    <hr class=\"title-divider\">\n    <div class=\"uk-text-center uk-margin-large-bottom\">\n      <div class=\"address-small\">{\'lp_address_city\' | config} {\'lp_address_street\' | config}</div>\n    </div>\n    <div class=\"uk-background-muted\" style=\"height: 600px\" id=\"map\"></div>\n  </div>\n</section>', 0, 'a:0:{}', 0, '');
INSERT INTO `YTxejLABtRB1_site_htmlsnippets` (`id`, `source`, `property_preprocess`, `name`, `description`, `editor_type`, `category`, `cache_type`, `snippet`, `locked`, `properties`, `static`, `static_file`) VALUES
(106, 4, 0, 'Form.email.Tpl', '', 0, 5, 0, '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Strict//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width\"/>\n<style type=\"text/css\">\n* { margin: 0; padding: 0; font-size: 100%; font-family: \"Helvetica Neue\", \"Helvetica\", Helvetica, Arial, sans-serif; line-height: 1.5em; }\nimg { max-width: 100%; margin: 0 auto; display: block; }\nbody, .body-wrap { width: 100% !important; height: 100%; background: #efefef; -webkit-font-smoothing: antialiased; -webkit-text-size-adjust: none; }\na { color: #71bc37; text-decoration: none; }\n.text-center { text-align: center; }\n.text-right { text-align: right; }\n.text-left { text-align: left; }\n.button { display: inline-block; color: white; background: #71bc37; border: solid #71bc37; border-width: 5px 10px 4px; font-weight: bold; border-radius: 2px; }\nhr { border-bottom: 4px solid #dedede !important; border: none; margin-bottom: 20px; }\nh1, h2, h3, h4, h5, h6 { margin-bottom: 20px; line-height: 1.15; }\nh1 { font-size: 28px; font-weight: normal; line-height:60px }\nh2 { font-size: 24px; }\nh3 { font-size: 20px; }\nh4 { font-size: 18px; font-weight: normal;}\nh5 { font-size: 16px; }\np, ul, ol { font-size: 16px; font-weight: normal; margin-bottom: 20px; }\n.container { display: block !important; clear: both !important; margin: 0 auto !important; max-width: 580px !important; }\n.container table { width: 100% !important; border-collapse: collapse; }\n.container .masthead { padding: 10px 0; background-color: #dedede; color: #444; line-height:60px; }\n.container .masthead h1 { margin: 0 auto !important; max-width: 90%; line-height: 80px }\n.container .content { background: white; padding: 30px 15px; line-height: 16px; font-size: 14px }\n.container .content.footer { background: none; }\n.container .content.footer p { margin-bottom: 0; color: #888; font-size: 14px; }\n.container .content.footer a { color: #888; text-decoration: none; font-weight: normal; }\n</style>\n</head>\n<body>\n<table class=\"body-wrap\">\n  <tr>\n    <td class=\"container\"><!-- Message start -->\n    <table>\n      <tr>\n        <td align=\"center\" class=\"masthead\">\n          <h4 style=\"margin-top:15px\">Заявка с сайта - Двероконгрупп</h4>\n        </td>\n      </tr>\n      <tr>\n        <td class=\"content\">\n          <table>\n            [[+goods:notempty=`\n            <tr>\n              <td width=\"120\" style=\"font-weight: bold; color:#666\">Товар / услуга</td>\n              <td align=\"left\">[[+goods]]</td>\n            </tr>\n            `]]\n            [[+price:notempty=`\n            <tr>\n              <td width=\"120\" style=\"font-weight: bold; color:#666\">Цена</td>\n              <td align=\"left\">[[+price]] руб.</td>\n            </tr>\n            `]]\n            [[+name:notempty=`\n            <tr>\n              <td width=\"120\" style=\"font-weight: bold; color:#666\">Имя</td>\n              <td align=\"left\">[[+name]]</td>\n            </tr>\n            `]]\n            [[+id_city_name:notempty=`\n            <tr>\n              <td width=\"120\" style=\"font-weight: bold; color:#666\">Город:</td>\n              <td align=\"left\">[[+id_city_name]]</td>\n            </tr>\n            `]]\n            <tr>\n              <td width=\"120\" style=\"font-weight: bold; color:#666\">Страница:</td>\n              <td align=\"left\">[[*menutitle:default=`[[*pagetitle]]`]] </td>\n            </tr>\n            [[+phone:notempty=`\n            <tr>\n              <td width=\"120\" style=\"font-weight: bold; color:#666\">Телефон:</td>\n              <td align=\"left\"><a href=\"tel:[[+phone]]\">[[+phone]]</a></td>\n            </tr>\n            `]]\n            [[+email:notempty=`\n            <tr>\n              <td width=\"120\" style=\"font-weight: bold; color:#666\">Email:</td>\n              <td align=\"left\"><a href=\"mailto:[[+email]]\">[[+email]]</a></td>\n            </tr>\n            `]]\n            [[+discount:notempty=`\n            <tr>\n              <td width=\"120\" style=\"font-weight: bold; color:#666\">Скидка:</td>\n              <td align=\"left\">[[+discount]] %</td>\n            </tr>\n            `]]\n            [[+doc:notempty=`\n            <tr>\n              <td width=\"120\" style=\"font-weight: bold; color:#666\">Договор:</td>\n              <td align=\"left\">[[+doc]] %</td>\n            </tr>\n            `]]\n            [[+comment:notempty=`\n            <tr>\n              <td width=\"120\" style=\"font-weight: bold; color:#666\" colspan=\"2\">Комментарий:</td>\n            </tr>\n            <tr>\n              <td align=\"left\"colspan=\"2\">[[+comment]]</td>\n            </tr>\n            `]]\n            [[+files:notempty=`\n            <tr>\n              <td width=\"120\" style=\"font-weight: bold; color:#666\">Файлы:</td>\n              <td align=\"left\"><a href=\"[[+files]]\">[[+files]]</a></td>\n            </tr>\n            `]]\n            </table></td>\n      </tr>\n  </table></td>\n  </tr>\n  <tr>\n    <td class=\"container\">\n      <table>\n        <tr>\n          <td class=\"content footer\" align=\"center\"><p> это сообщение отправлено автоматически и не требует ответа</p>\n            <p><a href=\"[[++site_url]]\">[[++site_name]]</a></p></td>\n        </tr>\n      </table></td>\n  </tr>\n</table>\n</body>\n</html>', 0, 'a:0:{}', 0, ''),
(107, 0, 0, 'Footer', '', 0, 3, 0, '<footer class=\"uk-section uk-section-small uk-section-secondary footer\">\n    <div class=\"uk-container\">\n      <div uk-grid>\n        <div class=\"uk-width-1-1@s uk-width-1-3@m uk-width-1-4@l uk-visible@l\">\n          <p class=\"uk-text-bold\">О компании</p>\n          <p class=\"uk-text-small\">{\'footer-descr\' | config}</p>\n        </div>\n        <div class=\"uk-width-1-1@s uk-width-1-3@m uk-width-1-4@l uk-visible@m\">\n          <p class=\"uk-text-bold\">Продукция</p>\n          <ul class=\"uk-nav\">\n            {$_modx->runSnippet(\'pdoMenu\', [\n              \'parents\' => 52,\n              \'resources\' => \'\',\n              \'fastMode\' => 1,\n              \'level\' => 0,\n              \'limit\' => 5,\n              \'cache\' => 1,\n              \'showHidden\' => 0,\n            	\'countChildren\' => 0,\n              \'hereClass\' => \'uk-active\',\n            	\'lastClass\' => \'0\',\n            	\'firstClass\' => \'0\',\n              \'tplOuter\' => \'@INLINE {{+wrapper}}\',\n              \'tpl\' => \'@INLINE <li {{+classes}}><a href=\"{{+link}}\" {{+attributes}}>{{+menutitle}}</a></li>\'\n            ])}\n          </ul>\n        </div>\n        <div class=\"uk-width-1-1@s uk-width-1-3@m uk-width-1-4@l uk-visible@m\">\n          <p class=\"uk-text-bold\">Услуги</p>\n          <ul class=\"uk-nav\">\n            {$_modx->runSnippet(\'pdoMenu\', [\n              \'parents\' => 84,\n              \'resources\' => \'\',\n              \'fastMode\' => 1,\n              \'level\' => 0,\n              \'limit\' => 5,\n              \'cache\' => 1,\n              \'showHidden\' => 0,\n            	\'countChildren\' => 0,\n              \'hereClass\' => \'uk-active\',\n            	\'lastClass\' => \'0\',\n            	\'firstClass\' => \'0\',\n              \'tplOuter\' => \'@INLINE {{+wrapper}}\',\n              \'tpl\' => \'@INLINE <li {{+classes}}><a href=\"{{+link}}\" {{+attributes}}>{{+menutitle}}</a></li>\'\n            ])}\n          </ul>\n        </div>\n        <div class=\"uk-width-1-1@s uk-width-1-3@m uk-width-1-4@l uk-visible@m\">\n          <p class=\"uk-text-bold\">Информация</p>\n          <ul class=\"uk-nav\">\n            {$_modx->runSnippet(\'pdoMenu\', [\n              \'parents\' => 0,\n              \'resources\' => \'9,50,84,76,69,51,90,89\',\n              \'fastMode\' => 1,\n              \'level\' => 5,\n              \'limit\' => 5,\n              \'cache\' => 1,\n              \'showHidden\' => 1,\n            	\'countChildren\' => 0,\n              \'hereClass\' => \'uk-active\',\n            	\'lastClass\' => \'0\',\n            	\'firstClass\' => \'0\',\n              \'tplOuter\' => \'@INLINE {{+wrapper}}\',\n              \'tpl\' => \'@INLINE <li {{+classes}}><a href=\"{{+link}}\" {{+attributes}}>{{+menutitle}}</a>{{+wrapper}}</li>\'\n            ])}\n          </ul>\n        </div>\n        <div class=\"uk-width-1-1 uk-text-small uk-text-muted uk-text-center\">\n          <a href=\"#\" uk-totop  uk-scroll></a>\n          [[!EasyCopyright? &Name=`` &PoweredBySeparator=`` &PoweredBy=`false` &Powered=`` &StartYear=`{\'lp_StartYear\' | config}`]]. Все права защищены. Сайт не является публичной офертой</div>\n      </div>\n    </div>\n  </footer>', 0, 'a:0:{}', 0, ''),
(109, 0, 0, 'Info.Folio', '', 0, 47, 0, '<section class=\"uk-section uk-section-large uk-section-muted porfolio\" id=\"pdopage\">\n  <div class=\"uk-grid uk-flex-center\" uk-grid>\n    <div class=\"uk-width-1-1 uk-width-3-4@m uk-width-3-5@l rows\">\n      {$_modx->runSnippet(\'!pdoPage@Paginations\', [\n        \'parents\' => 10,\n        \'tpl\' => \'Info.Folio.row\',\n        \'limit\' => 4,\n        \'cache\' => 1,\n        \'ajax\' => 1,\n        \'showLog\' => 0,\n        \'setMeta\' => 0,\n        \'ajaxHistory\' => 0,\n        \'frontend_css\' => 0,\n        \'ajaxMode\' => \'scroll\',\n        \'ajaxTplMore\' => \'@INLINE <div class=\"uk-text-center uk-width-1-1\"><button type=\"button\" class=\"uk-button uk-button-large uk-button-secondary uk-border-rounded btn-more uk-width-medium\"><span class=\"load-more\">Показать еще</span><span class=\"load-more-loading uk-hidden\" uk-spinner></span></button></div>\'\n      ])}\n    </div>\n    <div class=\"uk-width-1-1 uk-text-center\" hidden>\n      {$_modx->getPlaceholder(\'page.nav\')}\n    </div>\n  </div>\n</section>', 0, 'a:0:{}', 0, ''),
(110, 0, 0, 'Info.Folio.row', '', 0, 47, 0, '<div class=\"folioItem\">\n  <h6 class=\"folioItem__title uk-text-center uk-text-left@l\">{$pagetitle}</h6>\n  <div uk-slider=\"finite: true; sets: true\">\n    <div class=\"uk-position-relative\">\n      <div class=\"uk-slider-container uk-light\">\n        <ul class=\"uk-slider-items uk-child-width-1-2 uk-child-width-1-3@s uk-child-width-1-4@m folioItemSlider\" uk-lightbox>\n          {$_modx->runSnippet(\'ms2Gallery\', [\n            \'parents\' => 0,\n            \'resources\' => $id,\n            \'tpl\' => \'Info.Folio.Slider.row\',\n            \'limit\' => 8,\n            \'frontend_css\' => 0,\n            \'frontend_js\' => 0,\n            \'showLog\' => 0,\n            \'showInactive\' => 0\n          ])}\n        </ul>\n      </div>\n      <div class=\"uk-hidden@l uk-light\">\n        <a class=\"uk-position-center-left uk-position-small\" href=\"#\" uk-slidenav-previous uk-slider-item=\"previous\"></a>\n        <a class=\"uk-position-center-right uk-position-small\" href=\"#\" uk-slidenav-next uk-slider-item=\"next\"></a>\n      </div>\n      <div class=\"uk-visible@l\">\n        <a class=\"uk-position-center-left-out uk-position-small\" href=\"#\" uk-slidenav-previous uk-slider-item=\"previous\"></a>\n        <a class=\"uk-position-center-right-out uk-position-small\" href=\"#\" uk-slidenav-next uk-slider-item=\"next\"></a>\n      </div>\n    </div>\n  </div>\n  <div class=\"uk-margin-small-top uk-text-center uk-text-right@m\"><a href=\"{$uri}\" class=\"uk-button uk-button-text\">Смотреть всё</a></div>\n</div>\n', 0, 'a:0:{}', 0, ''),
(111, 0, 0, 'Info.Folio.Slider.row', '', 0, 47, 0, '{if $files?}\n  {foreach $files as $file}\n    <li><a href=\"{$file[\'large\']}\"><img class=\"folioItemSlider__item\" src=\"{$file[\'thumb\']}\" alt=\"{$file[\'name\']}\"></a></li>\n  {/foreach}\n{/if}', 0, 'a:0:{}', 0, ''),
(112, 1, 0, 'Contacts.Content', '', 0, 47, 0, '<div class=\"uk-section uk-section-small uk-section-mute\" style=\"border-top: 1px solid #e9e9e9\">\n	<div class=\"uk-container\">\n		<div class=\"uk-grid uk-flex-center\" uk-grid>\n		  <div class=\"uk-width-1-1\">\n		    <h1 class=\"uk-h1 uk-text-center\">{$_modx->resource.pagetitle}</h1>\n        <hr class=\"title-divider\">\n        <div class=\"uk-card uk-background-default uk-border-rounded uk-box-shadow-small\">\n          {include \'Contacts.Map\'}\n          <div class=\"uk-card-footer\">\n            <ul class=\"uk-list\">\n              <li>{$_modx->config.lp_address_city}, {$_modx->config.lp_address_street}</li>\n              {if $_modx->config.lp_phone ?}<li><a class=\"uk-button-text uk-link-reset\" href=\"tel:{$_modx->config.lp_phone | replace : \"(\" : \"\" | replace : \")\" : \"\" | replace : \"-\" : \"\" | replace : \" \" : \"\"}\"> {$_modx->config.lp_phone}</a></li> {/if}\n              {if $_modx->config.lp_phone_2 ?}<li><a class=\"uk-button-text uk-link-reset\" href=\"tel:{$_modx->config.lp_phone_2 | replace : \"(\" : \"\" | replace : \")\" : \"\" | replace : \"-\" : \"\" | replace : \" \" : \"\"}\"> {$_modx->config.lp_phone_2}</a></li> {/if}\n        			{if $_modx->config.lp_email ?}<li><a href=\"mailto:{$_modx->config.lp_email}\" class=\"uk-button-text uk-link-reset\"> {$_modx->config.lp_email}</a></li>{/if}\n              {if $_modx->config.lp_vk ?}<li> <a href=\"{$_modx->config.lp_vk}\" class=\"uk-button-text uk-link-reset\" target=\"_blank\">Группа Вконтакте</a></li>{/if}\n              {if $_modx->config.lp_in ?}<li> <a href=\"{$_modx->config.lp_in}\" class=\"uk-button-text uk-link-reset\" target=\"_blank\">Инстаграмм</a></li>{/if}\n            </ul>\n          </div>\n        </div>\n      </div>\n			{if $_modx->resource.content?}\n			<div class=\"uk-width-1-1 uk-width-3-4@m uk-width-3-5@l\">\n  			{$_modx->resource.content}\n  			{if $_modx->resource.parent == 10}\n  			{$_modx->getChunk(\'!Info.Content.Gallery\')}\n  			{/if}\n  			{if $_modx->resource.underContent ?}\n  			<div class=\"uk-margin-top\">{$_modx->resource.underContent}</div>\n  			{/if}\n			</div>\n			{/if}\n		</div>\n	</div>\n</div>', 0, 'a:0:{}', 0, ''),
(113, 0, 0, 'Info.Map', '', 0, 47, 0, '{ignore}\n<script>\n$(document).ready(function () { \n  $.getScript(\'https://api-maps.yandex.ru/2.1/?lang=ru-RU\').done(function (script, textStatus) {\n  ymaps.ready(init);\n    function init () { \n      var myMap = new ymaps.Map(\'map\', { \n          center: [ [[#9.map]] ],\n          zoom: 17,\n          controls: [\'zoomControl\',  \'fullscreenControl\'],\n        }),\n        objectManager = new ymaps.ObjectManager({\n          clusterize: true,\n          checkZoomRange:true,\n          gridSize: 48\n        });\n      myMap.behaviors.disable(\'scrollZoom\');\n      objectManager.objects.options.set(\'preset\', \'islands#redDotIcon\');\n      objectManager.clusters.options.set(\'preset\', \'islands#redClusterIcons\');\n      myMap.geoObjects.add(objectManager);\n      objectManager.add({ \"type\": \"FeatureCollection\", \"features\": \n        [{ \"type\": \"FeatureCollection\", \"features\": [ \n          {\n          	\'type\': \'Feature\',\n          	\'id\': 1,\n          	\'geometry\': { \'type\': \'Point\', \'coordinates\': [ [[#9.map]] ]},\n          	\'properties\': { \'balloonContent\': \'<b>[[++site_name]]</b>\',\'clusterCaption\': \'[[++site_name]]\',\'hintContent\':    \'[[++site_name]]\'}\n          }\n        ]}\n      ]});\n    }\n  });\n});\n</script>\n{/ignore}\n<div class=\"uk-height-medium\" id=\"map\"></div>', 0, 'a:0:{}', 0, ''),
(114, 4, 0, 'Services', '', 0, 47, 0, '<ul class=\"uk-grid uk-grid-small uk-child-width-1-1 uk-child-width-1-2@s uk-child-width-1-3@m\" uk-grid uk-height-match=\"target: .uk-card\">\n  {$_modx->runSnippet(\'!ms2GalleryResources\', [\n    \'parents\' => $_modx->resource.id,\n    \'tpl\' => \'Services.row\',\n    \'limit\' => 0,\n    \'frontend_css\' => 0,\n    \'frontend_js\' => 0,\n    \'showLog\' => 0,\n    \'showInactive\' => 0,\n    \'includeThumbs\' => \'thumb\',\n    \'typeOfJoin\' => \'left\',\n    \'fastMode\' => 1,\n    \'sortby\' => \'menuindex\',\n    \'sortdir\' => \'ASC\'\n  ])}\n</ul>', 0, 'a:0:{}', 0, ''),
(115, 0, 0, 'Services.row', '', 0, 47, 0, '<li>\n  <div class=\"uk-card uk-card-small uk-card-default\">\n    <div class=\"uk-card-media-top\">\n      {if $thumb ?}\n      <img src=\"{$thumb}\" alt=\"{$pagetitle}\">\n      {else}\n      <img src=\"/tpl/img/all-foto.jpg\" alt=\"{$pagetitle}\">\n      {/if}\n    </div>\n    <div class=\"uk-card-body uk-text-center\">\n      <h4 class=\"uk-card-title\">{$pagetitle}</h4>\n      {if $introtext?}<p class=\"uk-text-small\">{$introtext}</p>{/if}\n    </div>\n  </div>\n</li>', 0, 'a:0:{}', 0, ''),
(116, 0, 0, 'Price.Row', '', 0, 47, 0, '<tr>\n  <td class=\"uk-text-center uk-text-left@m\">[[+name]]</td>\n  <td class=\"uk-text-center\">[[+options]]</td>\n  <td class=\"uk-text-center uk-text-bold\">[[+price]] руб.</td>\n</tr>', 0, 'a:0:{}', 0, ''),
(117, 4, 0, 'Price', '', 0, 47, 0, '<div class=\"uk-width-xlarge\">\n  <h3 class=\"uk-h2\">Прайс-лист на услугу</h3>\n  <table class=\"uk-width-1-1 uk-table uk-table-divider uk-table-striped uk-table-hover uk-table-small uk-table-middle uk-table-responsive\">\n    <thead>\n      <tr>\n        <th class=\"uk-table-expand uk-text-small\">Материал</th>\n        <th class=\"uk-text-small\">Толщина</th>\n        <th class=\"uk-text-small\">Цена за п.м.</th>\n      </tr>\n    </thead>\n    <tbody>\n      {$_modx->runSnippet(\'getImageList\', [\n        \'tvname\' => \'Price\',\n        \'limit\' => 0,\n        \'tpl\' => \'Price.Row\',\n        \'docid\' => $_modx->resource.id\n      ])}\n    </tbody>\n  </table>\n</div>', 0, 'a:0:{}', 0, ''),
