(119, 0, 0, 'Home.Header.Top', '', 0, 31, 0, '<div class=\"header-main-top uk-light uk-visible@m\">\n  <div class=\"uk-container\">\n    <ul class=\"uk-subnav uk-flex uk-flex-right@l uk-flex-center\">\n      <li class=\"uk-active\"><a href=\"{89 | url}\"><span uk-icon=\"cog\" class=\"uk-text-danger\"></span>\n        <span class=\"header-main-top--link\"> Все способы оплаты</span></a></li>\n      <li><a href=\"{75 | url}\"><span uk-icon=\"cog\" class=\"uk-text-danger\"></span> <span class=\"header-main-top--link\"> Готовые двери и окна</span></a>\n      </li>\n      <li><a href=\"{76 | url}\"><span uk-icon=\"cog\" class=\"uk-text-danger\"></span> <span class=\"header-main-top--link\"> Отзывы</span></a></li>\n      <li><a href=\"#boss\" uk-toggle=\"target: #boss\"><span uk-icon=\"cog\" class=\"uk-text-danger\"></span>\n        <span class=\"header-main-top--link\"> Написать директору</span></a></li>\n    </ul>\n  </div>\n</div>', 0, 'a:0:{}', 0, ''),
(120, 0, 0, 'Home.Header.Nav', '', 0, 31, 0, '<div class=\"header-main-nav\">\n  <div class=\"uk-container\">\n    <div class=\"uk-grid-small header-main-nav--contacts uk-flex-middle\" uk-grid>\n      <div class=\"uk-width-auto@m\">\n        <a href=\"index.html\" class=\"uk-navbar-item uk-logo\"><img class=\"logo\" src=\"tpl/img/logo.png\" alt=\"Дверокон\" title=\"Дверокон\" width=\"200\" height=\"73\"></a>\n      </div>\n      <div class=\"uk-width-expand uk-flex uk-flex-center@l uk-flex-right uk-visible@xl\">\n        <div>\n          <div class=\"uk-flex-middle uk-flex\">\n            <span uk-icon=\"icon: receiver; ratio: .9\" class=\"uk-text-danger uk-margin-small-right\"></span>\n            <a href=\"tel:{\'lp_phone\' | config | replace : \"(\" : \"\" | replace : \")\" : \"\" | replace : \"-\" : \"\" | replace : \" \" : \"\"}\" class=\"uk-text-large font-bold uk-link-reset\">{\'lp_phone\' | config}</a>\n          </div>\n          <div class=\"uk-flex-middle uk-flex\"><span uk-icon=\"icon: clock; ratio: .8\" class=\"uk-text-danger uk-margin-small-right\"></span>\n            <span class=\"uk-text-muted uk-text-small\"> {\'lp_phone_2\' | config}</span></div>\n        </div>\n      </div>\n      <div class=\"uk-width-auto@l uk-width-expand uk-text-right uk-visible@m\">\n        <button type=\"button\" class=\"uk-button uk-button-default uk-margin-small-right\" uk-toggle=\"target: #callback\">Заявка на расчет</button>\n        <button type=\"button\" class=\"uk-button uk-button-default danger\" uk-toggle=\"target: #callback\">Бесплатный замер</button>\n      </div>\n    </div>\n    <hr class=\"header-main-nav--contacts-border\">\n  </div>\n  <nav class=\"navbar\" uk-sticky=\"animation: uk-animation-slide-top; top: 100;\">\n    <div class=\"uk-container\">\n      <div uk-navbar>\n        <div class=\"uk-navbar-left uk-hidden@l\">\n          <a class=\"uk-navbar-toggle\" href=\"#side-menu\" uk-toggle> <span uk-navbar-toggle-icon></span>\n            <span class=\"uk-margin-small-left uk-visible@s\">Меню</span> </a>\n        </div>\n        <div class=\"uk-navbar-center uk-visible@l navbar--nav\">\n          <ul class=\"uk-navbar-nav\">\n             {include \'Nav.top\'}\n          </ul>\n        </div>\n        <div class=\"uk-navbar-right navbar--phone\">\n          <button type=\"button\" style=\"line-height:40px\" class=\"uk-button uk-button-danger uk-margin-small-right\" uk-toggle=\"target: #callback\">Заявка на расчет</button>\n          <a class=\"uk-navbar-item uk-margin-remove\" href=\"tel:{\'lp_phone\' | config | replace : \"(\" : \"\" | replace : \")\" : \"\" | replace : \"-\" : \"\" | replace : \" \" : \"\"}\">{\'lp_phone\' | config}</a>\n        </div>\n      </div>\n    </div>\n  </nav>\n</div>', 0, 'a:0:{}', 0, ''),
(121, 0, 0, 'Home.Header.Content', '', 0, 31, 0, '<div class=\"header-main--content uk-background-cover uk-background-secondary uk-position-relative js-lozad\"\n    data-background-image=\"[[+ms2g.0.xlarge]]\" uk-parallax=\"bgy: -200\">\n  <div class=\"header-main--overlay\"></div>\n  <div class=\"uk-container uk-position-relative uk-position-z-index\">\n    <div class=\"uk-flex-middle\" uk-grid>\n      <div class=\"uk-width-auto@l uk-width-1-1 uk-text-center uk-text-left@l\"><img class=\"header-main--content__img\" src=\"tpl/img/bgrd/278.png\">\n      </div>\n      <div class=\"uk-width-expand@l uk-width-1-1 uk-text-center uk-text-left@l\">\n        <p class=\"header-main--title\">{\'introtext\' | resource}</p>\n        <p class=\"header-main--subtitle\">Самое лучшее акционное предложение 2025 года</p>\n        <div><button type=\"button\" class=\"uk-button uk-button-large uk-button-danger\" uk-toggle=\"#callback\">Заказать по акции</button></div>\n      </div>\n    </div>\n  </div>\n</div>', 0, 'a:0:{}', 0, ''),
(122, 0, 0, 'Home.Content', '', 0, 31, 0, '<section class=\"uk-section uk-section-default uk-section-large\">\n  <div class=\"uk-container\">\n    <div class=\"uk-flex-center\" uk-grid>\n      <div class=\"uk-width-1-1\">\n        <p class=\"uk-h1\">{\'introtext\' | resource}</p>\n      </div>\n      <div class=\"uk-width-1-1 uk-width-auto@l uk-flex-last@l uk-text-center\">\n        <img data-src=\"tpl/img/images/paluba.jpg\" alt=\"\" title=\"\" width=\"400\" class=\"lozad\">\n      </div>\n      <div class=\"uk-width-expand@l uk-width-1-1  uk-text-large\">\n        {\'content\' | resource}\n      </div>\n    </div>\n  </div>\n</section>', 0, 'a:0:{}', 0, ''),
(124, 0, 0, 'Home.Products', '', 0, 31, 0, '<section class=\"uk-section uk-section-default\">\n  <div class=\"uk-container\">\n    <h2 class=\"uk-h1 uk-text-center\"><span class=\"uk-text-danger\">Продукция</span> компании Дверокон</h2>\n    <hr class=\"title-divider\">\n    <ul class=\"uk-grid-small uk-child-width-1-1 uk-child-width-1-2@s uk-child-width-1-3@m uk-child-width-1-4@l services\" uk-grid\n        uk-scrollspy=\"cls: uk-animation-fade uk-invisible; target: > li > .service; delay: 300; repeat: false\">\n      {$_modx->runSnippet(\'!ms2GalleryResources\', [\n        \'parents\' => 52,\n        \'tpl\' => \'Home.Products.Row\',\n        \'limit\' => 0,\n        \'frontend_css\' => 0,\n        \'frontend_js\' => 0,\n        \'depth\' => 0,\n        \'showInactive\' => 0,\n        \'includeThumbs\' => \'thumb\',\n        \'fastMode\' => 1,\n        \'sortby\' => \'menuindex\',\n        \'sortdir\' => \'ASC\'\n      ])}\n    </ul>\n  </div>\n</section>', 0, 'a:0:{}', 0, ''),
(125, 0, 0, 'Home.News.Gramoty', '<div uk-slider=\"finite: true; sets:true\">\n        <div class=\"uk-position-relative uk-visible-toggle uk-light\" uk-lightbox>\n          <ul class=\"uk-slider-items uk-child-width-1-2 uk-child-wi', 0, 31, 0, '<div uk-slider=\"finite: true; sets:true\">\n  <div class=\"uk-position-relative uk-visible-toggle uk-light\" uk-lightbox>\n    <ul class=\"uk-slider-items uk-child-width-1-2 uk-child-width-1-3@s uk-child-width-1-4@m uk-child-width-1-5@l gramoty\">\n      {$_modx->runSnippet(\'!ms2Gallery\', [\n        \'parents\' => 0,\n        \'resources\' => 56,\n        \'tpl\' => \'Home.News.Gramoty.Row\',\n        \'limit\' => 0,\n        \'cache\' => 1,\n        \'frontend_css\' => 0,\n        \'frontend_js\' => 0,\n      ])}\n    </ul>\n  </div>\n  <ul class=\"uk-slider-nav uk-dotnav uk-flex-center uk-margin\"></ul>\n</div>', 0, 'a:0:{}', 0, ''),
(126, 0, 0, 'Home.Products.Row', '', 0, 31, 0, '<li>\n  <aside class=\"service uk-invisible js-lozad\" data-background-image=\"{$thumb}\">\n    <canvas class=\"service--sizer large\" width=\"600\" height=\"800\"></canvas>\n    <canvas class=\"service--sizer small\" width=\"800\" height=\"300\"></canvas>\n    <div class=\"service--title\">{$menutitle}</div>\n    <a href=\"{$uri}\" class=\"uk-position-cover\"></a>\n  </aside>\n</li>', 0, 'a:0:{}', 0, ''),
