(129, 4, 0, 'Home.Discount', '', 0, 31, 0, '<section class=\"discount\" id=\"js-discount\"\n    uk-scrollspy=\"cls:uk-animation-fade; delay: 30; repeat: false\">\n  <div class=\"discount-item\" uk-parallax=\"y: -30%\">\n    <div class=\"discount-item--red\"><span>специаальное предложение</span></div>\n    <div class=\"discount-item--content uk-flex uk-flex-middle uk-flex-center\">\n      <div>\n        <div class=\"discount-item--title\">Ваша скидка</div>\n        <div class=\"discount-item--count\"><span class=\"js-discount discount-item--count_counter\"\n            data-from=\"0\" data-to=\"{\'discount_max\' | config}\" data-speed=\"{\'discount_time\' | config}\" data-decimals=\"3\" data-refresh-interval=\"3\"></span><span class=\"discount-item--count__persent\">%</span>\n        </div>\n        <button type=\"button\" class=\"uk-button-default uk-button danger uk-margin-top\" uk-toggle=\"target: #discount\" id=\"js-discountGet\">Получить скидку</button>\n      </div>\n    </div>\n  </div>\n</section>\n{include \'Home.Discount.Form\'}', 0, 'a:0:{}', 0, ''),
(130, 0, 0, 'Home.Discount.Form.Tpl', '', 0, 5, 0, '<div id=\"discount\" uk-modal>\n  <form class=\"uk-modal-dialog uk-margin-auto-vertical ajax_form\" method=\"post\" enctype=\"multipart/form-data\">\n    <button class=\"uk-modal-close-default\" type=\"button\" uk-close></button>\n    <div class=\"uk-modal-header\">\n      <div class=\"uk-margin\">\n        <div class=\"discount-block uk-text-center uk-hidden\">\n          <p class=\"uk-h1 uk-text-uppercase uk-margin-remove\">Ваша скидка:</p>\n          <p class=\"uk-margin-remove uk-heading-hero uk-text-success text-light\"><span class=\"discount-total\"></span>%\n          </p>\n        </div>\n      </div>\n      <div class=\"uk-margin\">\n        <p class=\"uk-h2 uk-text-uppercase uk-text-center text-color-dark\">Получить скидку!</p>\n      </div>\n    </div>\n    <div class=\"uk-modal-body uk-form-horizontal\">\n      <div class=\"uk-hidden\">\n  		    <input type=\"hidden\" value=\"\" id=\"discount-total\" name=\"discount\">\n        <input type=\"email\" id=\"af_works_email\" name=\"works_email\" value=\"[[+fi.works_email]]\">\n        [[!cityselect? &frontend_css=`0` &frontend_js=`0` &tpl=`tpl.CitySelect`]]\n		  </div>\n      <div class=\"uk-grid-small uk-grid\" uk-grid>\n        <div class=\"uk-width-1-1 uk-width-1-2@s\">\n          <div class=\"uk-inline uk-width-1-1\">\n            <span class=\"uk-form-icon uk-form-icon-flip\" uk-icon=\"icon: user\"></span>\n            <input class=\"uk-input uk-width-1-1\" type=\"text\" placeholder=\"Ваше Имя\" name=\"name\" value=\"[[+name]]\">\n          </div>\n        </div>\n        <div class=\"uk-width-1-1 uk-width-1-2@s\">\n          <div class=\"uk-inline uk-width-1-1\">\n            <span class=\"uk-form-icon uk-form-icon-flip\" uk-icon=\"icon: phone\"></span>\n            <input class=\"uk-input phone uk-width-1-1\" type=\"text\" placeholder=\"Ваш номер телефона\" name=\"phone\" value=\"[[+phone]]\">\n          </div>\n        </div>\n      </div>\n    </div>\n    <div class=\"uk-modal-footer uk-text-center\">\n      <button class=\"uk-button uk-button-danger\">Получить</button>\n    </div>\n  </form>\n</div>', 0, 'a:0:{}', 0, ''),
(131, 1, 0, 'Home.Discount.Form', '', 0, 5, 0, '[[!AjaxForm? \n  &form=`Home.Discount.Form.Tpl`\n  &hooks=`spam,email,FormItSaveForm`\n  &formName=`Заявка с сайта Двероконгрупп`\n  &allowFiles=`0`\n    \n  &emailSubject=`Заявка с сайта Двероконгрупп`\n  &emailTo=`[[++lp_email_notyfy]]`\n  &emailFrom=`[[++lp_email_from]]`\n  &emailFromName=`[[++site_name]]`\n  &emailTpl=`Form.email.Tpl`\n  \n  &validate=`name:required,phone:required,works_email:blank`\n  &validationErrorMessage=`В форме содержатся ошибки!`\n  &successMessage=`Сообщение успешно отправлено`\n  \n  &frontend_js=`` \n  &frontend_css=``\n]]', 0, 'a:0:{}', 0, ''),
(133, 0, 0, 'Home.Reason', '', 0, 47, 0, '  <div class=\"uk-section uk-section-default\">\n    <div class=\"uk-container\">\n      <h4 class=\"uk-h2 uk-margin-top\">12 причин выбрать велокс для строительства своего дома</h4>\n      <div class=\"reason\">\n        <div class=\"uk-grid-collapse\" uk-grid>\n          <div class=\"uk-width-expand\">\n            <!--reason row 1-->\n            <div class=\"uk-grid-collapse reasonRow--border__bottom\" uk-grid>\n              <div class=\"uk-width-auto@l uk-width-1-1\">\n                <div class=\"reasonRowTitle\">\n                  <div class=\"uk-position-cover reasonRowTitle--trianglify\" id=\"trianglify_1\"></div>\n                  <span>Надежный</span>\n                </div>\n              </div>\n              <div class=\"uk-width-expand@l uk-width-1-1\">\n                <div class=\"uk-grid-collapse uk-child-width-1-2 uk-child-width-1-4@m reasonRow--border\" uk-grid>\n                  <div>\n                    <div class=\"reasonRowItem\">\n                      <canvas width=\"600\" height=\"600\"></canvas>\n                      <div class=\"reasonRowItem--container\">\n                        <span class=\"sprite--reason__1_1\"></span>\n                        <div>Капитальное и безопасное строение</div>\n                      </div>\n                    </div>\n                  </div>\n                  <div>\n                    <div class=\"reasonRowItem\">\n                      <canvas width=\"600\" height=\"600\"></canvas>\n                      <div class=\"reasonRowItem--container\">\n                        <span class=\"sprite--reason__1_2\"></span>\n                        <div>Капитальное и безопасное строение</div>\n                      </div>\n                    </div>\n                  </div>\n                  <div>\n                    <div class=\"reasonRowItem\">\n                      <canvas width=\"600\" height=\"600\"></canvas>\n                      <div class=\"reasonRowIte