(13, 1, 0, 'MinifyX', 'MinifyX is a snippet the allows you to combine and minify JS and CSS files', 0, 9, 0, '/** @var array $scriptProperties */\r\n/** @var MinifyX $MinifyX */\r\nif (isset($modx->minifyx) && $modx->minifyx instanceof MinifyX) {\r\n    $MinifyX = $modx->minifyx;\r\n    $MinifyX->reset($scriptProperties);\r\n} else {\r\n    $MinifyX = $modx->getService(\'minifyx\', \'MinifyX\', MODX_CORE_PATH . \'components/minifyx/model/minifyx/\', $scriptProperties);\r\n}\r\n\r\n$sources = $MinifyX->prepareSources();\r\n\r\nforeach ($sources as $type => $value) {\r\n    if (empty($value)) {continue;}\r\n//    $filename = $MinifyX->config[$type.\'Filename\'] . \'_\';\r\n//    $extension = $MinifyX->config[$type.\'Ext\'];\r\n    $register = $MinifyX->config[\'register\'.ucfirst($type)];\r\n    $placeholder = !empty($MinifyX->config[$type.\'Placeholder\'])\r\n        ? $MinifyX->config[$type.\'Placeholder\']\r\n        : \'\';\r\n\r\n    $files = $MinifyX->prepareFiles($value, $type);\r\n    $properties = array(\r\n        \'minify\' => $MinifyX->config[\'minify\'.ucfirst($type)]\r\n            ? \'true\'\r\n            : \'false\',\r\n    );\r\n    $result = $MinifyX->Munee($files, $properties);\r\n    // Register file on frontend\r\n    if ($MinifyX->saveFile($result)) {\r\n        $tag = str_replace(\'[[+file]]\', $MinifyX->getFileUrl(), $type == \'css\' ? $cssTpl : $jsTpl);\r\n        switch ($register) {\r\n        	case \'placeholder\':\r\n                if ($register == \'placeholder\' && $placeholder) {\r\n                    $modx->setPlaceholder($placeholder, $tag);\r\n                }\r\n        		break;\r\n            case \'print\':\r\n                return $tag;\r\n            default:\r\n                if ($type == \'css\') {\r\n                    $modx->regClientCSS($tag);\r\n                }\r\n                else {\r\n                    if ($register == \'startup\') {\r\n                        $modx->regClientStartupScript($tag);\r\n                    }\r\n                    else {\r\n                        $modx->regClientScript($tag);\r\n                    }\r\n                }\r\n        }\r\n    }\r\n}\r\n\r\nreturn;', 0, 'a:17:{s:9:\"jsSources\";a:7:{s:4:\"name\";s:9:\"jsSources\";s:4:\"desc\";s:22:\"minifyx_prop_jsSources\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:18:\"minifyx:properties\";s:4:\"area\";s:0:\"\";}s:10:\"cssSources\";a:7:{s:4:\"name\";s:10:\"cssSources\";s:4:\"desc\";s:23:\"minifyx_prop_cssSources\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:18:\"minifyx:properties\";s:4:\"area\";s:0:\"\";}s:8:\"minifyJs\";a:7:{s:4:\"name\";s:8:\"minifyJs\";s:4:\"desc\";s:21:\"minifyx_prop_minifyJs\";s:4:\"type\";s:13:\"combo-boolean\";s:7:\"options\";a:0:{}s:5:\"value\";b:0;s:7:\"lexicon\";s:18:\"minifyx:properties\";s:4:\"area\";s:0:\"\";}s:9:\"minifyCss\";a:7:{s:4:\"name\";s:9:\"minifyCss\";s:4:\"desc\";s:22:\"minifyx_prop_minifyCss\";s:4:\"type\";s:13:\"combo-boolean\";s:7:\"options\";a:0:{}s:5:\"value\";b:0;s:7:\"lexicon\";s:18:\"minifyx:properties\";s:4:\"area\";s:0:\"\";}s:10:\"jsFilename\";a:7:{s:4:\"name\";s:10:\"jsFilename\";s:4:\"desc\";s:23:\"minifyx_prop_jsFilename\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:7:\"scripts\";s:7:\"lexicon\";s:18:\"minifyx:properties\";s:4:\"area\";s:0:\"\";}s:11:\"cssFilename\";a:7:{s:4:\"name\";s:11:\"cssFilename\";s:4:\"desc\";s:24:\"minifyx_prop_cssFilename\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:6:\"styles\";s:7:\"lexicon\";s:18:\"minifyx:properties\";s:4:\"area\";s:0:\"\";}s:10:\"registerJs\";a:7:{s:4:\"name\";s:10:\"registerJs\";s:4:\"desc\";s:23:\"minifyx_prop_registerJs\";s:4:\"type\";s:4:\"list\";s:7:\"options\";a:4:{i:0;a:2:{s:5:\"value\";s:11:\"placeholder\";s:4:\"text\";s:11:\"Placeholder\";}i:1;a:2:{s:5:\"value\";s:7:\"startup\";s:4:\"text\";s:14:\"Startup script\";}i:2;a:2:{s: