(16, 1, 0, 'Jevix', 'HTML validator and filter', 0, 14, 0, '/** @var array $scriptProperties */\n/** @var Jevix $Jevix */\nif (!$modx->loadClass(\'jevix\', MODX_CORE_PATH . \'components/jevix/model/jevix/\', false, true)) {\n	return \'Could not load Jevix!\';\n}\nelseif (empty($input)) {\n	return \'\';\n}\n\nif (!empty($options) && is_string($options) && $options[0] == \'{\') {\n	$scriptProperties = $modx->fromJSON($options);\n}\n\n$Jevix = new Jevix($modx, $scriptProperties);\n$processed = $Jevix->process($input);\n\nif (!empty($scriptProperties[\'escapeTags\'])) {\n	$processed = str_replace(\n		array(\'[\', \']\', \'`\', \'{\', \'}\'),\n		array(\'&#91;\', \'&#93;\', \'&#96;\', \'&#123;\', \'&#125;\'),\n		$processed\n	);\n}\n\nreturn $processed;', 0, 'a:21:{s:5:\"input\";a:7:{s:4:\"name\";s:5:\"input\";s:4:\"desc\";s:16:\"jevix_prop_input\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:16:\"jevix:properties\";s:4:\"area\";s:0:\"\";}s:5:\"debug\";a:7:{s:4:\"name\";s:5:\"debug\";s:4:\"desc\";s:16:\"jevix_prop_debug\";s:4:\"type\";s:13:\"combo-boolean\";s:7:\"options\";a:0:{}s:5:\"value\";b:0;s:7:\"lexicon\";s:16:\"jevix:properties\";s:4:\"area\";s:0:\"\";}s:9:\"logErrors\";a:7:{s:4:\"name\";s:9:\"logErrors\";s:4:\"desc\";s:20:\"jevix_prop_logErrors\";s:4:\"type\";s:13:\"combo-boolean\";s:7:\"options\";a:0:{}s:5:\"value\";b:0;s:7:\"lexicon\";s:16:\"jevix:properties\";s:4:\"area\";s:0:\"\";}s:10:\"escapeTags\";a:7:{s:4:\"name\";s:10:\"escapeTags\";s:4:\"desc\";s:21:\"jevix_prop_escapeTags\";s:4:\"type\";s:13:\"combo-boolean\";s:7:\"options\";a:0:{}s:5:\"value\";b:0;s:7:\"lexicon\";s:16:\"jevix:properties\";s:4:\"area\";s:0:\"\";}s:17:\"cfgAllowTagParams\";a:7:{s:4:\"name\";s:17:\"cfgAllowTagParams\";s:4:\"desc\";s:28:\"jevix_prop_cfgAllowTagParams\";s:4:\"type\";s:8:\"textarea\";s:7:\"options\";a:0:{}s:5:\"value\";s:163:\"{\"a\":[\"title\",\"href\"],\"img\":{\"0\":\"src\",\"alt\":\"#text\",\"1\":\"title\",\"align\":[\"rig