nt\";a:7:{s:4:\"name\";s:14:\"includeContent\";s:4:\"desc\";s:23:\"ms2_prop_includeContent\";s:4:\"type\";s:13:\"combo-boolean\";s:7:\"options\";a:0:{}s:5:\"value\";b:0;s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:10:\"includeTVs\";a:7:{s:4:\"name\";s:10:\"includeTVs\";s:4:\"desc\";s:19:\"ms2_prop_includeTVs\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:13:\"includeThumbs\";a:7:{s:4:\"name\";s:13:\"includeThumbs\";s:4:\"desc\";s:22:\"ms2_prop_includeThumbs\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:13:\"optionFilters\";a:7:{s:4:\"name\";s:13:\"optionFilters\";s:4:\"desc\";s:22:\"ms2_prop_optionFilters\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:5:\"where\";a:7:{s:4:\"name\";s:5:\"where\";s:4:\"desc\";s:14:\"ms2_prop_where\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:4:\"link\";a:7:{s:4:\"name\";s:4:\"link\";s:4:\"desc\";s:13:\"ms2_prop_link\";s:4:\"type\";s:11:\"numberfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:6:\"master\";a:7:{s:4:\"name\";s:6:\"master\";s:4:\"desc\";s:15:\"ms2_prop_master\";s:4:\"type\";s:11:\"numberfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:5:\"slave\";a:7:{s:4:\"name\";s:5:\"slave\";s:4:\"desc\";s:14:\"ms2_prop_slave\";s:4:\"type\";s:11:\"numberfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:8:\"tvPrefix\";a:7:{s:4:\"name\";s:8:\"tvPrefix\";s:4:\"desc\";s:17:\"ms2_prop_tvPrefix\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:15:\"outputSeparator\";a:7:{s:4:\"name\";s:15:\"outputSeparator\";s:4:\"desc\";s:24:\"ms2_prop_outputSeparator\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:1:\"\n\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:9:\"returnIds\";a:7:{s:4:\"name\";s:9:\"returnIds\";s:4:\"desc\";s:18:\"ms2_prop_returnIds\";s:4:\"type\";s:13:\"combo-boolean\";s:7:\"options\";a:0:{}s:5:\"value\";b:0;s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:15:\"showUnpublished\";a:7:{s:4:\"name\";s:15:\"showUnpublished\";s:4:\"desc\";s:24:\"ms2_prop_showUnpublished\";s:4:\"type\";s:13:\"combo-boolean\";s:7:\"options\";a:0:{}s:5:\"value\";b:0;s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:11:\"showDeleted\";a:7:{s:4:\"name\";s:11:\"showDeleted\";s:4:\"desc\";s:20:\"ms2_prop_showDeleted\";s:4:\"type\";s:13:\"combo-boolean\";s:7:\"options\";a:0:{}s:5:\"value\";b:0;s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:10:\"showHidden\";a:7:{s:4:\"name\";s:10:\"showHidden\";s:4:\"desc\";s:19:\"ms2_prop_showHidden\";s:4:\"type\";s:13:\"combo-boolean\";s:7:\"options\";a:0:{}s:5:\"value\";b:1;s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:13:\"showZeroPrice\";a:7:{s:4:\"name\";s:13:\"showZeroPrice\";s:4:\"desc\";s:22:\"ms2_prop_showZeroPrice\";s:4:\"type\";s:13:\"combo-boolean\";s:7:\"options\";a:0:{}s:5:\"value\";b:1;s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:11:\"wrapIfEmpty\";a:7:{s:4:\"name\";s:11:\"wrapIfEmpty\";s:4:\"desc\";s:20:\"ms2_prop_wrapIfEmpty\";s:4:\"type\";s:13:\"combo-boolean\";s:7:\"options\";a:0:{}s:5:\"value\";b:1;s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}}', '', 0, 'core/components/minishop2/elements/snippets/snippet.ms_products.php'),
(71, 1, 0, 'msCart', '', 0, 58, 0, '/** @var modX $modx */\n/** @var array $scriptProperties */\n/** @var miniShop2 $miniShop2 */\n$miniShop2 = $modx->getService(\'miniShop2\');\n$miniShop2->initialize($modx->context->key);\n/** @var pdoFetch $pdoFetch */\nif (!$modx->loadClass(\'pdofetch\', MODX_CORE_PATH . \'components/pdotools/model/pdotools/\', false, true)) {\n    return false;\n}\n$pdoFetch = new pdoFetch($modx, $scriptProperties);\n$pdoFetch->addTime(\'pdoTools loaded.\');\n\n$tpl = $modx->getOption(\'tpl\', $scriptProperties, \'tpl.msCart\');\n$cart = $miniShop2->cart->get();\n$status = $miniShop2->cart->status();\n\n// Do not show empty cart when displaying order details\nif (!empty($_GET[\'msorder\'])) {\n    return \'\';\n} elseif (empty($status[\'total_count\'])) {\n    return $pdoFetch->getChunk($tpl);\n}\n\n// Select cart products\n$where = array(\n    \'msProduct.id:IN\' => array(),\n);\nforeach ($cart as $entry) {\n    $where[\'msProduct.id:IN\'][] = $entry[\'id\'];\n}\n$where[\'msProduct.id:IN\'] = array_unique($where[\'msProduct.id:IN\']);\n\n// Include products properties\n$leftJoin = array(\n    \'Data\' => array(\n        \'class\' => \'msProductData\',\n    ),\n    \'Vendor\' => array(\n        \'class\' => \'msVendor\',\n        \'on\' => \'Data.vendor = Vendor.id\',\n    ),\n);\n\n// Select columns\n$select = array(\n    \'msProduct\' => !empty($includeContent)\n        ? $modx->getSelectColumns(\'msProduct\', \'msProduct\')\n        : $modx->getSelectColumns(\'msProduct\', \'msProduct\', \'\', array(\'content\'), true),\n    \'Data\' => $modx->getSelectColumns(\'msProductData\', \'Data\', \'\', array(\'id\'), true),\n    \'Vendor\' => $modx->getSelectColumns(\'msVendor\', \'Vendor\', \'vendor.\', array(\'id\'), true),\n);\n\n// Include products thumbnails\nif (!empty($includeThumbs)) {\n    $thumbs = array_map(\'trim\', explode(\',\', $includeThumbs));\n    if (!empty($thumbs[0])) {\n        foreach ($thumbs as $thumb) {\n            $leftJoin[$thumb] = array(\n                \'class\' => \'msProductFile\',\n                \'on\' => \"`{$thumb}`.product_id = msProduct.id AND `{$thumb}`.parent != 0 AND `{$thumb}`.path LIKE \'%/{$thumb}/%\' AND `{$thumb}`.rank = 0\",\n            );\n            $select[$thumb] = \"`{$thumb}`.url as \'{$thumb}\'\";\n        }\n        $pdoFetch->addTime(\'Included list of thumbnails: <b>\' . implode(\', \', $thumbs) . \'</b>.\');\n    }\n}\n\n// Add user parameters\nforeach (array(\'where\', \'leftJoin\', \'select\') as $v) {\n    if (!empty($scriptProperties[$v])) {\n        $tmp = $scriptProperties[$v];\n        if (!is_array($tmp)) {\n            $tmp = json_decode($tmp, true);\n        }\n        if (is_array($tmp)) {\n            $$v = array_merge($$v, $tmp);\n        }\n    }\n    unset($scriptProperties[$v]);\n}\n$pdoFetch->addTime(\'Conditions prepared\');\n\n$default = array(\n    \'class\' => \'msProduct\',\n    \'where\' => $where,\n    \'leftJoin\' => $leftJoin,\n    \'select\' => $select,\n    \'sortby\' => \'msProduct.id\',\n    \'sortdir\' => \'ASC\',\n    \'groupby\' => \'msProduct.id\',\n    \'limit\' => 0,\n    \'return\' => \'data\',\n    \'nestedChunkPrefix\' => \'minishop2_\',\n);\n// Merge all properties and run!\n$pdoFetch->setConfig(array_merge($default, $scriptProperties), false);\n\n$tmp = $pdoFetch->run();\n$rows = array();\nforeach ($tmp as $row) {\n    $rows[$row[\'id\']] = $row;\n}\n\n// Process products in cart\n$products = array();\n$total = array(\'count\' => 0, \'weight\' => 0, \'cost\' => 0);\nforeach ($cart as $key => $entry) {\n    if (!isset($rows[$entry[\'id\']])) {\n        continue;\n    }\n    $product = $rows[$entry[\'id\']];\n\n    $product[\'key\'] = $key;\n    $product[\'count\'] = $entry[\'count\'];\n    $product[\'old_price\'] = $miniShop2->formatPrice(\n        $product[\'price\'] > $entry[\'price\']\n            ? $product[\'price\']\n            : $product[\'old_price\']\n    );\n    $product[\'price\'] = $miniShop2->formatPrice($entry[\'price\']);\n    $product[\'weight\'] = $miniShop2->formatWeight($entry[\'weight\']);\n    $product[\'cost\'] = $miniShop2->formatPrice($entry[\'count\'] * $entry[\'price\']);\n\n    // Additional properties of product in cart\n    if (!empty($entry[\'options\']) && is_array($entry[\'options\'])) {\n        $product[\'options\'] = $entry[\'options\'];\n        foreach ($entry[\'options\'] as $option => $value) {\n            $product[\'option.\' . $option] = $value;\n        }\n    }\n\n    // Add option values\n    $options = $modx->call(\'msProductData\', \'loadOptions\', array(&$modx, $product[\'id\']));\n    $products[] = array_merge($product, $options);\n\n    // Count total\n    $total[\'count\'] += $entry[\'count\'];\n    $total[\'cost\'] += $entry[\'count\'] * $entry[\'price\'];\n    $total[\'weight\'] += $entry[\'count\'] * $entry[\'weight\'];\n}\n$total[\'cost\'] = $miniShop2->formatPrice($total[\'cost\']);\n$total[\'weight\'] = $miniShop2->formatWeight($total[\'weight\']);\n\n$output = $pdoFetch->getChunk($tpl, array(\n    \'total\' => $total,\n    \'products\' => $products,\n));\n\nif ($modx->user->hasSessionContext(\'mgr\') && !empty($showLog)) {\n    $output .= \'<pre class=\"msCartLog\">\' . print_r($pdoFetch->getTime(), true) . \'</pre>\';\n}\n\nif (!empty($toPlaceholder)) {\n    $modx->setPlaceholder($toPlaceholder, $output);\n} else {\n    return $output;\n}', 0, 'a:5:{s:3:\"tpl\";a:7:{s:4:\"name\";s:3:\"tpl\";s:4:\"desc\";s:12:\"ms2_prop_tpl\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:10:\"tpl.msCart\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:10:\"includeTVs\";a:7:{s:4:\"name\";s:10:\"includeTVs\";s:4:\"desc\";s:19:\"ms2_prop_includeTVs\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:13:\"includeThumbs\";a:7:{s:4:\"name\";s:13:\"includeThumbs\";s:4:\"desc\";s:22:\"ms2_prop_includeThumbs\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:13:\"toPlaceholder\";a:7:{s:4:\"name\";s:13:\"toPlaceholder\";s:4:\"desc\";s:22:\"ms2_prop_toPlaceholder\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:7:\"showLog\";a:7:{s:4:\"name\";s:7:\"showLog\";s:4:\"desc\";s:16:\"ms2_prop_showLog\";s:4:\"type\";s:13:\"combo-boolean\";s:7:\"options\";a:0:{}s:5:\"value\";b:0;s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}}', '', 0, 'core/components/minishop2/elements/snippets/snippet.ms_cart.php'),
(72, 1, 0, 'msMiniCart', '', 0, 58, 0, '/** @var modX $modx */\n/** @var array $scriptProperties */\n/** @var miniShop2 $miniShop2 */\n$miniShop2 = $modx->getService(\'miniShop2\');\n$miniShop2->initialize($modx->context->key);\n\n$tpl = $modx->getOption(\'tpl\', $scriptProperties, \'tpl.msMiniCart\');\n\n$cart = $miniShop2->cart->status();\n$cart[\'total_cost\'] = $miniShop2->formatPrice($cart[\'total_cost\']);\n$cart[\'total_weight\'] = $miniShop2->formatWeight($cart[\'total_weight\']);\n\nreturn $miniShop2->pdoTools->getChunk($tpl, $cart);', 0, 'a:1:{s:3:\"tpl\";a:7:{s:4:\"name\";s:3:\"tpl\";s:4:\"desc\";s:12:\"ms2_prop_tpl\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:14:\"tpl.msMiniCart\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}}', '', 0, 'core/components/minishop2/elements/snippets/snippet.ms_minicart.php'),
(73, 1, 0, 'msGallery', '', 0, 58, 0, '/** @var modX $modx */\n/** @var array $scriptProperties */\n/** @var miniShop2 $miniShop2 */\n$miniShop2 = $modx->getService(\'miniShop2\');\n$miniShop2->initialize($modx->context->key);\n/** @var pdoFetch $pdoFetch */\nif (!$modx->loadClass(\'pdofetch\', MODX_CORE_PATH . \'components/pdotools/model/pdotools/\', false, true)) {\n    return false;\n}\n$pdoFetch = new pdoFetch($modx, $scriptProperties);\n$pdoFetch->addTime(\'pdoTools loaded.\');\n\n$extensionsDir = $modx->getOption(\'extensionsDir\', $scriptProperties, \'components/minishop2/img/mgr/extensions/\', true);\n$limit = $modx->getOption(\'limit\', $scriptProperties, 0);\n$tpl = $modx->getOption(\'tpl\', $scriptProperties, \'tpl.msGallery\');\n\n/** @var msProduct $product */\n$product = !empty($product) && $product != $modx->resource->id\n    ? $modx->getObject(\'msProduct\', $product)\n    : $modx->resource;\nif (!$product || !($product instanceof msProduct)) {\n    return \"[msGallery] The resource with id = {$product->id} is not instance of msProduct.\";\n}\n\n$where = array(\n    \'product_id\' => $product->id,\n    \'parent\' => 0,\n);\nif (!empty($filetype)) {\n    $where[\'type:IN\'] = array_map(\'trim\', explode(\',\', $filetype));\n}\nif (empty($showInactive)) {\n    $where[\'active\'] = 1;\n}\n$select = array(\n    \'msProductFile\' => \'*\',\n);\n\n// Add user parameters\nforeach (array(\'where\') as $v) {\n    if (!empty($scriptProperties[$v])) {\n        $tmp = $scriptProperties[$v];\n        if (!is_array($tmp)) {\n            $tmp = json_decode($tmp, true);\n        }\n        if (is_array($tmp)) {\n            $$v = array_merge($$v, $tmp);\n        }\n    }\n    unset($scriptProperties[$v]);\n}\n$pdoFetch->addTime(\'Conditions prepared\');\n\n$default = array(\n    \'class\' => \'msProductFile\',\n    \'where\' => $where,\n    \'select\' => $select,\n    \'limit\' => $limit,\n    \'sortby\' => \'rank\',\n    \'sortdir\' => \'ASC\',\n    \'fastMode\' => false,\n    \'return\' => \'data\',\n    \'nestedChunkPrefix\' => \'minishop2_\',\n);\n// Merge all properties and run!\n$pdoFetch->setConfig(array_merge($default, $scriptProperties), false);\n$rows = $pdoFetch->run();\n\n$pdoFetch->addTime(\'Fetching thumbnails\');\n\n$resolution = array();\n/** @var msProductData $data */\nif ($data = $product->getOne(\'Data\')) {\n    if ($data->initializeMediaSource()) {\n        $properties = $data->mediaSource->getProperties();\n        if (isset($properties[\'thumbnails\'][\'value\'])) {\n            $fileTypes = json_decode($properties[\'thumbnails\'][\'value\'], true);\n            foreach ($fileTypes as $k => $v) {\n                if (!is_numeric($k)) {\n                    $resolution[] = $k;\n                } elseif (!empty($v[\'name\'])) {\n                    $resolution[] = $v[\'name\'];\n                } else {\n                    $resolution[] = @$v[\'w\'] . \'x\' . @$v[\'h\'];\n                }\n            }\n        }\n    }\n}\n\n// Processing rows\n$files = array();\nforeach ($rows as $row) {\n    if (isset($row[\'type\']) && $row[\'type\'] == \'image\') {\n        $c = $modx->newQuery(\'msProductFile\', array(\'parent\' => $row[\'id\']));\n        $c->select(\'product_id,url\');\n        $tstart = microtime(true);\n        if ($c->prepare() && $c->stmt->execute()) {\n            $modx->queryTime += microtime(true) - $tstart;\n            $modx->executedQueries++;\n            while ($tmp = $c->stmt->fetch(PDO::FETCH_ASSOC)) {\n                if (preg_match(\"#/{$tmp[\'product_id\']}/(.*?)/#\", $tmp[\'url\'], $size)) {\n                    $row[$size[1]] = $tmp[\'url\'];\n                }\n            }\n        }\n    } elseif (isset($row[\'type\'])) {\n        $row[\'thumbnail\'] =\n        $row[\'url\'] = file_exists(MODX_ASSETS_PATH . $extensionsDir . $row[\'type\'] . \'.png\')\n            ? MODX_ASSETS_URL . $extensionsDir . $row[\'type\'] . \'.png\'\n            : MODX_ASSETS_URL . $extensionsDir . \'other.png\';\n        foreach ($resolution as $v) {\n            $row[$v] = $row[\'thumbnail\'];\n        }\n    }\n\n    $files[] = $row;\n}\n\n$output = $pdoFetch->getChunk($tpl, array(\n    \'files\' => $files,\n));\n\nif ($modx->user->hasSessionContext(\'mgr\') && !empty($showLog)) {\n    $output .= \'<pre class=\"msGalleryLog\">\' . print_r($pdoFetch->getTime(), 1) . \'</pre>\';\n}\n\nif (!empty($toPlaceholder)) {\n    $modx->setPlaceholder($toPlaceholder, $output);\n} else {\n    return $output;\n}', 0, 'a:10:{s:7:\"product\";a:7:{s:4:\"name\";s:7:\"product\";s:4:\"desc\";s:16:\"ms2_prop_product\";s:4:\"type\";s:11:\"numberfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:3:\"tpl\";a:7:{s:4:\"name\";s:3:\"tpl\";s:4:\"desc\";s:12:\"ms2_prop_tpl\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:13:\"tpl.msGallery\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:5:\"limit\";a:7:{s:4:\"name\";s:5:\"limit\";s:4:\"desc\";s:14:\"ms2_prop_limit\";s:4:\"type\";s:11:\"numberfield\";s:7:\"options\";a:0:{}s:5:\"value\";i:0;s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:6:\"offset\";a:7:{s:4:\"name\";s:6:\"offset\";s:4:\"desc\";s:15:\"ms2_prop_offset\";s:4:\"type\";s:11:\"numberfield\";s:7:\"options\";a:0:{}s:5:\"value\";i:0;s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:6:\"sortby\";a:7:{s:4:\"name\";s:6:\"sortby\";s:4:\"desc\";s:15:\"ms2_prop_sortby\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:4:\"rank\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:7:\"sortdir\";a:7:{s:4:\"name\";s:7:\"sortdir\";s:4:\"desc\";s:16:\"ms2_prop_sortdir\";s:4:\"type\";s:4:\"list\";s:7:\"options\";a:2:{i:0;a:2:{s:4:\"text\";s:3:\"ASC\";s:5:\"value\";s:3:\"ASC\";}i:1;a:2:{s:4:\"text\";s:4:\"DESC\";s:5:\"value\";s:4:\"DESC\";}}s:5:\"value\";s:3:\"ASC\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:13:\"toPlaceholder\";a:7:{s:4:\"name\";s:13:\"toPlaceholder\";s:4:\"desc\";s:22:\"ms2_prop_toPlaceholder\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:7:\"showLog\";a:7:{s:4:\"name\";s:7:\"showLog\";s:4:\"desc\";s:16:\"ms2_prop_showLog\";s:4:\"type\";s:13:\"combo-boolean\";s:7:\"options\";a:0:{}s:5:\"value\";b:0;s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:5:\"where\";a:7:{s:4:\"name\";s:5:\"where\";s:4:\"desc\";s:14:\"ms2_prop_where\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:8:\"filetype\";a:7:{s:4:\"name\";s:8:\"filetype\";s:4:\"desc\";s:17:\"ms2_prop_filetype\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}}', '', 0, 'core/components/minishop2/elements/snippets/snippet.ms_gallery.php'),
(74, 1, 0, 'msOptions', '', 0, 58, 0, '/** @var modX $modx */\n/** @var array $scriptProperties */\n$tpl = $modx->getOption(\'tpl\', $scriptProperties, \'tpl.msOptions\');\nif (!empty($input) && empty($product)) {\n    $product = $input;\n}\nif (!empty($name) && empty($options)) {\n    $options = $name;\n}\n\n$product = !empty($product) && $product != $modx->resource->id\n    ? $modx->getObject(\'msProduct\', $product)\n    : $modx->resource;\nif (!($product instanceof msProduct)) {\n    return \"[msOptions] The resource with id = {$product->id} is not instance of msProduct.\";\n}\n\n$names = array_map(\'trim\', explode(\',\', $options));\n$options = array();\nforeach ($names as $name) {\n    if (!empty($name) && $option = $product->get($name)) {\n        if (!is_array($option)) {\n            $option = array($option);\n        }\n        if (!empty($option[0])) {\n            $options[$name] = $option;\n        }\n    }\n}\n\n/** @var pdoTools $pdoTools */\n$pdoTools = $modx->getService(\'pdoTools\');\n\nreturn $pdoTools->getChunk($tpl, array(\n    \'id\' => $product->id,\n    \'options\' => $options,\n));', 0, 'a:3:{s:7:\"product\";a:7:{s:4:\"name\";s:7:\"product\";s:4:\"desc\";s:16:\"ms2_prop_product\";s:4:\"type\";s:11:\"numberfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:7:\"options\";a:7:{s:4:\"name\";s:7:\"options\";s:4:\"desc\";s:16:\"ms2_prop_options\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:3:\"tpl\";a:7:{s:4:\"name\";s:3:\"tpl\";s:4:\"desc\";s:12:\"ms2_prop_tpl\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:13:\"tpl.msOptions\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}}', '', 0, 'core/components/minishop2/elements/snippets/snippet.ms_options.php'),
(75, 1, 0, 'msOrder', '', 0, 58, 0, '/** @var modX $modx */\n/** @var array $scriptProperties */\n/** @var miniShop2 $miniShop2 */\n$miniShop2 = $modx->getService(\'miniShop2\');\n$miniShop2->initialize($modx->context->key);\n/** @var pdoFetch $pdoFetch */\nif (!$modx->loadClass(\'pdofetch\', MODX_CORE_PATH . \'components/pdotools/model/pdotools/\', false, true)) {\n    return false;\n}\n$pdoFetch = new pdoFetch($modx, $scriptProperties);\n$pdoFetch->addTime(\'pdoTools loaded.\');\n\n$tpl = $modx->getOption(\'tpl\', $scriptProperties, \'tpl.msOrder\');\n\n// Do not show order form when displaying details of existing order\nif (!empty($_GET[\'msorder\'])) {\n    return \'\';\n}\n\n$cart = $miniShop2->cart->get();\n$order = $miniShop2->order->get();\n$status = $miniShop2->cart->status();\nif (empty($status[\'total_count\'])) {\n    return \'\';\n}\n$cost = $miniShop2->order->getCost();\n$order[\'cost\'] = $miniShop2->formatPrice($cost[\'data\'][\'cost\']);\n\n// We need only active methods\n$where = array(\n    \'msDelivery.active\' => true,\n    \'msPayment.active\' => true,\n);\n\n// Join payments to deliveries\n$leftJoin = array(\n    \'Payments\' => array(\n        \'class\' => \'msDeliveryMember\',\n    ),\n    \'msPayment\' => array(\n        \'class\' => \'msPayment\',\n        \'on\' => \'Payments.payment_id = msPayment.id\',\n    ),\n);\n\n// Select columns\n$select = array(\n    \'msDelivery\' => $modx->getSelectColumns(\'msDelivery\', \'msDelivery\', \'delivery_\'),\n    \'msPayment\' => $modx->getSelectColumns(\'msPayment\', \'msPayment\', \'payment_\'),\n);\n\n// Add user parameters\nforeach (array(\'where\', \'leftJoin\', \'select\') as $v) {\n    if (!empty($scriptProperties[$v])) {\n        $tmp = $scriptProperties[$v];\n        if (!is_array($tmp)) {\n            $tmp = json_decode($tmp, true);\n        }\n        if (is_array($tmp)) {\n            $$v = array_merge($$v, $tmp);\n        }\n    }\n    unset($scriptProperties[$v]);\n}\n$pdoFetch->addTime(\'Conditions prepared\');\n\n// Default parameters\n$default = array(\n    \'class\' => \'msDelivery\',\n    \'where\' => $where,\n    \'leftJoin\' => $leftJoin,\n    \'select\' => $select,\n    \'sortby\' => \'msDelivery.rank asc, msPayment.rank\',\n    \'sortdir\' => \'asc\',\n    \'limit\' => 0,\n    \'return\' => \'data\',\n    \'nestedChunkPrefix\' => \'minishop2_\',\n);\n// Merge all properties and run!\n$pdoFetch->setConfig(array_merge($default, $scriptProperties), false);\n$rows = $pdoFetch->run();\n\n$deliveries = $payments = array();\nforeach ($rows as $row) {\n    $delivery = array();\n    $payment = array();\n    foreach ($row as $key => $value) {\n        if (strpos($key, \'delivery_\') === 0) {\n            $delivery[substr($key, 9)] = $value;\n        } else {\n            $payment[substr($key, 8)] = $value;\n        }\n    }\n\n    if (!isset($deliveries[$delivery[\'id\']])) {\n        $delivery[\'payments\'] = array();\n        $deliveries[$delivery[\'id\']] = $delivery;\n    }\n    if (!empty($payment[\'id\'])) {\n        $deliveries[$delivery[\'id\']][\'payments\'][] = (int)$payment[\'id\'];\n        if (!isset($payments[$payment[\'id\']])) {\n            $payments[$payment[\'id\']] = $payment;\n        }\n    }\n}\n\n$form = array();\n// Get user data\n$profile = array();\nif ($modx->user->isAuthenticated($modx->context->key)) {\n    $profile = array_merge($modx->user->Profile->toArray(), $modx->user->toArray());\n}\n$fields = array(\n    \'receiver\' => \'fullname\',\n    \'phone\' => \'phone\',\n    \'email\' => \'email\',\n    \'comment\' => \'extended[comment]\',\n    \'index\' => \'zip\',\n    \'country\' => \'country\',\n    \'region\' => \'state\',\n    \'city\' => \'city\',\n    \'street\' => \'address\',\n    \'building\' => \'extended[building]\',\n    \'room\' => \'extended[room]\',\n);\n// Apply custom fields\nif (!empty($userFields)) {\n    if (!is_array($userFields)) {\n        $userFields = json_decode($userFields, true);\n    }\n    if (is_array($userFields)) {\n        $fields = array_merge($fields, $userFields);\n    }\n}\n// Set user fields\nforeach ($fields as $key => $value) {\n    if (!empty($profile) && !empty($value)) {\n        if (strpos($value, \'extended\') !== false) {\n            $tmp = substr($value, 9, -1);\n            $value = !empty($profile[\'extended\'][$tmp])\n                ? $profile[\'extended\'][$tmp]\n                : \'\';\n        } else {\n            $value = $profile[$value];\n        }\n        $response = $miniShop2->order->add($key, $value);\n        if ($response[\'success\'] && !empty($response[\'data\'][$key])) {\n            $form[$key] = $response[\'data\'][$key];\n        }\n    }\n    if (empty($form[$key]) && !empty($order[$key])) {\n        $form[$key] = $order[$key];\n        unset($order[$key]);\n    }\n}\n\n// Check for errors\n$errors = array();\nif (!empty($_POST)) {\n    $response = $miniShop2->order->getDeliveryRequiresFields();\n    if ($requires = $response[\'data\'][\'requires\']) {\n        foreach ($_POST as $field => $val) {\n            $validated = $miniShop2->order->validate($field, $val);\n            if ((in_array($field, $requires) && empty($validated))) {\n                $errors[] = $field;\n            }\n        }\n    }\n\n}\n\n$output = $pdoFetch->getChunk($tpl, array(\n    \'order\' => $order,\n    \'form\' => $form,\n    \'deliveries\' => $deliveries,\n    \'payments\' => $payments,\n    \'errors\' => $errors,\n));\n\nif ($modx->user->hasSessionContext(\'mgr\') && !empty($showLog)) {\n    $output .= \'<pre class=\"msOrderLog\">\' . print_r($pdoFetch->getTime(), true) . \'</pre>\';\n}\n\nreturn $output;', 0, 'a:3:{s:3:\"tpl\";a:7:{s:4:\"name\";s:3:\"tpl\";s:4:\"desc\";s:12:\"ms2_prop_tpl\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:11:\"tpl.msOrder\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:10:\"userFields\";a:7:{s:4:\"name\";s:10:\"userFields\";s:4:\"desc\";s:19:\"ms2_prop_userFields\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:7:\"showLog\";a:7:{s:4:\"name\";s:7:\"showLog\";s:4:\"desc\";s:16:\"ms2_prop_showLog\";s:4:\"type\";s:13:\"combo-boolean\";s:7:\"options\";a:0:{}s:5:\"value\";b:0;s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}}', '', 0, 'core/components/minishop2/elements/snippets/snippet.ms_order.php');
INSERT INTO `YTxejLABtRB1_site_snippets` (`id`, `source`, `property_preprocess`, `name`, `description`, `editor_type`, `category`, `cache_type`, `snippet`, `locked`, `properties`, `moduleguid`, `static`, `static_file`) VALUES
(76, 1, 0, 'msGetOrder', '', 0, 58, 0, '/** @var modX $modx */\n/** @var array $scriptProperties */\n/** @var miniShop2 $miniShop2 */\n$miniShop2 = $modx->getService(\'miniShop2\');\n$miniShop2->initialize($modx->context->key);\n/** @var pdoFetch $pdoFetch */\nif (!$modx->loadClass(\'pdofetch\', MODX_CORE_PATH . \'components/pdotools/model/pdotools/\', false, true)) {\n    return false;\n}\n$pdoFetch = new pdoFetch($modx, $scriptProperties);\n$pdoFetch->addTime(\'pdoTools loaded.\');\n\n$tpl = $modx->getOption(\'tpl\', $scriptProperties, \'tpl.msGetOrder\');\n\nif (empty($id) && !empty($_GET[\'msorder\'])) {\n    $id = (int)$_GET[\'msorder\'];\n}\nif (empty($id)) {\n    return;\n}\n/** @var msOrder $order */\nif (!$order = $modx->getObject(\'msOrder\', $id)) {\n    return $modx->lexicon(\'ms2_err_order_nf\');\n}\n$canView = (!empty($_SESSION[\'minishop2\'][\'orders\']) && in_array($id, $_SESSION[\'minishop2\'][\'orders\'])) ||\n    $order->get(\'user_id\') == $modx->user->id || $modx->user->hasSessionContext(\'mgr\') || !empty($scriptProperties[\'id\']);\nif (!$canView) {\n    return \'\';\n}\n\n// Select ordered products\n$where = array(\n    \'msOrderProduct.order_id\' => $id,\n);\n\n// Include products properties\n$leftJoin = array(\n    \'msProduct\' => array(\n        \'class\' => \'msProduct\',\n        \'on\' => \'msProduct.id = msOrderProduct.product_id\',\n    ),\n    \'Data\' => array(\n        \'class\' => \'msProductData\',\n        \'on\' => \'msProduct.id = Data.id\',\n    ),\n    \'Vendor\' => array(\n        \'class\' => \'msVendor\',\n        \'on\' => \'Data.vendor = Vendor.id\',\n    ),\n);\n\n// Select columns\n$select = array(\n    \'msProduct\' => !empty($includeContent)\n        ? $modx->getSelectColumns(\'msProduct\', \'msProduct\')\n        : $modx->getSelectColumns(\'msProduct\', \'msProduct\', \'\', array(\'content\'), true),\n    \'Data\' => $modx->getSelectColumns(\'msProductData\', \'Data\', \'\', array(\'id\'),\n            true) . \',`Data`.`price` as `original_price`\',\n    \'Vendor\' => $modx->getSelectColumns(\'msVendor\', \'Vendor\', \'vendor.\', array(\'id\'), true),\n    \'OrderProduct\' => $modx->getSelectColumns(\'msOrderProduct\', \'msOrderProduct\', \'\', array(\'id\'), true),\n);\n\n// Include products thumbnails\nif (!empty($includeThumbs)) {\n    $thumbs = array_map(\'trim\', explode(\',\', $includeThumbs));\n    if (!empty($thumbs[0])) {\n        foreach ($thumbs as $thumb) {\n            $leftJoin[$thumb] = array(\n                \'class\' => \'msProductFile\',\n                \'on\' => \"`{$thumb}`.product_id = msProduct.id AND `{$thumb}`.parent != 0 AND `{$thumb}`.path LIKE \'%/{$thumb}/%\'\",\n            );\n            $select[$thumb] = \"`{$thumb}`.url as \'{$thumb}\'\";\n        }\n        $pdoFetch->addTime(\'Included list of thumbnails: <b>\' . implode(\', \', $thumbs) . \'</b>.\');\n    }\n}\n\n// Add user parameters\nforeach (array(\'where\', \'leftJoin\', \'select\') as $v) {\n    if (!empty($scriptProperties[$v])) {\n        $tmp = $scriptProperties[$v];\n        if (!is_array($tmp)) {\n            $tmp = json_decode($tmp, true);\n        }\n        if (is_array($tmp)) {\n            $$v = array_merge($$v, $tmp);\n        }\n    }\n    unset($scriptProperties[$v]);\n}\n$pdoFetch->addTime(\'Conditions prepared\');\n\n// Tables for joining\n$default = array(\n    \'class\' => \'msOrderProduct\',\n    \'where\' => $where,\n    \'leftJoin\' => $leftJoin,\n    \'select\' => $select,\n    \'joinTVsTo\' => \'msProduct\',\n    \'sortby\' => \'msOrderProduct.id\',\n    \'sortdir\' => \'asc\',\n    \'groupby\' => \'msOrderProduct.id\',\n    \'fastMode\' => false,\n    \'limit\' => 0,\n    \'return\' => \'data\',\n    \'decodeJSON\' => true,\n    \'nestedChunkPrefix\' => \'minishop2_\',\n);\n// Merge all properties and run!\n$pdoFetch->setConfig(array_merge($default, $scriptProperties), true);\n$rows = $pdoFetch->run();\n\n$products = array();\n$cart_count = 0;\nforeach ($rows as $product) {\n    $product[\'old_price\'] = $miniShop2->formatPrice(\n        $product[\'original_price\'] > $product[\'price\']\n            ? $product[\'original_price\']\n            : $product[\'old_price\']\n    );\n    $product[\'price\'] = $miniShop2->formatPrice($product[\'price\']);\n    $product[\'cost\'] = $miniShop2->formatPrice($product[\'cost\']);\n    $product[\'weight\'] = $miniShop2->formatWeight($product[\'weight\']);\n\n    $product[\'id\'] = (int)$product[\'id\'];\n    if (empty($product[\'name\'])) {\n        $product[\'name\'] = $product[\'pagetitle\'];\n    } else {\n        $product[\'pagetitle\'] = $product[\'name\'];\n    }\n\n    // Additional properties of product\n    if (!empty($product[\'options\']) && is_array($product[\'options\'])) {\n        foreach ($product[\'options\'] as $option => $value) {\n            $product[\'option.\' . $option] = $value;\n        }\n    }\n\n    // Add option values\n    $options = $modx->call(\'msProductData\', \'loadOptions\', array(&$modx, $product[\'id\']));\n    $products[] = array_merge($product, $options);\n\n    // Count total\n    $cart_count += $product[\'count\'];\n}\n\n$total = array(\n    \'cost\' => $miniShop2->formatPrice($order->get(\'cost\')),\n    \'cart_cost\' => $miniShop2->formatPrice($order->get(\'cart_cost\')),\n    \'delivery_cost\' => $miniShop2->formatPrice($order->get(\'delivery_cost\')),\n    \'weight\' => $miniShop2->formatWeight($order->get(\'weight\')),\n    \'cart_weight\' => $miniShop2->formatWeight($order->get(\'weight\')),\n    \'cart_count\' => $cart_count,\n);\n\n$output = $pdoFetch->getChunk($tpl, array_merge($scriptProperties, array(\n    \'order\' => $order->toArray(),\n    \'products\' => $products,\n    \'user\' => ($tmp = $order->getOne(\'User\'))\n        ? array_merge($tmp->getOne(\'Profile\')->toArray(), $tmp->toArray())\n        : array(),\n    \'address\' => ($tmp = $order->getOne(\'Address\'))\n        ? $tmp->toArray()\n        : array(),\n    \'delivery\' => ($tmp = $order->getOne(\'Delivery\'))\n        ? $tmp->toArray()\n        : array(),\n    \'payment\' => ($tmp = $order->getOne(\'Payment\'))\n        ? $tmp->toArray()\n        : array(),\n    \'total\' => $total,\n)));\n\nif ($modx->user->hasSessionContext(\'mgr\') && !empty($showLog)) {\n    $output .= \'<pre class=\"msGetOrderLog\">\' . print_r($pdoFetch->getTime(), true) . \'</pre>\';\n}\n\nif (!empty($toPlaceholder)) {\n    $modx->setPlaceholder($toPlaceholder, $output);\n} else {\n    return $output;\n}', 0, 'a:5:{s:3:\"tpl\";a:7:{s:4:\"name\";s:3:\"tpl\";s:4:\"desc\";s:12:\"ms2_prop_tpl\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:14:\"tpl.msGetOrder\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:10:\"includeTVs\";a:7:{s:4:\"name\";s:10:\"includeTVs\";s:4:\"desc\";s:19:\"ms2_prop_includeTVs\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:13:\"includeThumbs\";a:7:{s:4:\"name\";s:13:\"includeThumbs\";s:4:\"desc\";s:22:\"ms2_prop_includeThumbs\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:13:\"toPlaceholder\";a:7:{s:4:\"name\";s:13:\"toPlaceholder\";s:4:\"desc\";s:22:\"ms2_prop_toPlaceholder\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}s:7:\"showLog\";a:7:{s:4:\"name\";s:7:\"showLog\";s:4:\"desc\";s:16:\"ms2_prop_showLog\";s:4:\"type\";s:13:\"combo-boolean\";s:7:\"options\";a:0:{}s:5:\"value\";b:0;s:7:\"lexicon\";s:20:\"minishop2:properties\";s:4:\"area\";s:0:\"\";}}', '', 0, 'core/components/minishop2/elements/snippets/snippet.ms_get_order.php'),
(77, 1, 0, 'msProductOptions', '', 0, 58, 0, '/** @var modX $modx */\n/** @var array $scriptProperties */\n\n$tpl = $modx->getOption(\'tpl\', $scriptProperties, \'tpl.msOptions\');\nif (!empty($input) && empty($product)) {\n    $product = $input;\n}\n\n$product = !empty($product) && $product != $modx->resource->id\n    ? $modx->getObject(\'msProduct\', $product)\n    : $modx->resource;\nif (!($product instanceof msProduct)) {\n    return \"[msProductOptions] The resource with id = {$product->id} is not instance of msProduct.\";\n}\n\n$ignoreOptions = array_map(\'trim\', explode(\',\', $modx->getOption(\'ignoreOptions\', $scriptProperties, \'\')));\n$onlyOptions = array_map(\'trim\', explode(\',\', $modx->getOption(\'onlyOptions\', $scriptProperties, \'\')));\n$groups = !empty($groups)\n    ? array_map(\'trim\', explode(\',\', $groups))\n    : array();\n/** @var msProductData $data */\nif ($data = $product->getOne(\'Data\')) {\n    $optionKeys = $data->getOptionKeys();\n}\nif (empty($optionKeys)) {\n    return \'\';\n}\n$productData = $product->loadOptions();\n\n$options = array();\nforeach ($optionKeys as $key) {\n    // Filter by key\n    if (!empty($onlyOptions) && $onlyOptions[0] != \'\' && !in_array($key, $onlyOptions)) {\n        continue;\n    } elseif (in_array($key, $ignoreOptions)) {\n        continue;\n    }\n    $option = array();\n    foreach ($productData as $dataKey => $dataValue) {\n        $dataKey = explode(\'.\', $dataKey);\n        if ($dataKey[0] == $key && (count($dataKey) > 1)) {\n            $option[$dataKey[1]] = $dataValue;\n        }\n    }\n    $option[\'value\'] = $product->get($key);\n\n    // Filter by groups\n    $skip = !empty($groups) && !in_array($option[\'category\'], $groups) && !in_array($option[\'category_name\'], $groups);\n    if ($skip || empty($option[\'value\'])) {\n        continue;\n    }\n    $options[$key] = $option;\n}\n\n/** @var pdoTools $pdoTools */\n$pdoTools = $modx->getService(\'pdoTools\');\n\nreturn $pdoTools->