p(\'packages-breadcrumbs\');\n                    var trail= bc.data.trail;\n                    trail.pop();\n\n                    if (trail.length > 1) {\n                        last = trail[trail.length - 1];\n\n                        if (last != undefined && last.rec != undefined) {\n                            bc.data.trail.pop();\n                            bc.data.trail.shift();\n                            bc.updateDetail(bc.data);\n\n                            var grid = Ext.getCmp(\'modx-package-grid\');\n                            grid.install(last.rec);\n                            return;\n                        }\n                    }\n\n                    this.activate();\n					Ext.getCmp(\'modx-package-grid\').refresh();\n                },scope:this}\n                ,\'failure\': {fn:function() {\n                    this.activate();\n                },scope:this}\n            }\n        });\n\n        return true;\n	}\";s:8:\"disabled\";s:5:\"false\";s:5:\"scope\";s:15:\"[object Object]\";s:9:\"autoWidth\";s:4:\"true\";s:10:\"autoHeight\";s:4:\"true\";s:8:\"minWidth\";s:2:\"75\";s:10:\"removeMode\";s:9:\"container\";s:10:\"hideParent\";s:4:\"true\";s:6:\"events\";s:15:\"[object Object]\";s:7:\"ownerCt\";s:15:\"[object Object]\";s:9:\"container\";s:15:\"[object Object]\";s:8:\"rendered\";s:4:\"true\";s:8:\"template\";s:15:\"[object Object]\";s:5:\"btnEl\";s:15:\"[object Object]\";s:4:\"mons\";s:15:\"[object Object]\";s:2:\"el\";s:15:\"[object Object]\";s:4:\"icon\";s:0:\"\";s:7:\"iconCls\";s:0:\"\";s:8:\"boxReady\";s:4:\"true\";s:11:\"useSetClass\";s:4:\"true\";s:6:\"oldCls\";s:12:\"x-btn-noicon\";s:3:\"doc\";s:15:\"[object Object]\";s:19:\"monitoringMouseOver\";s:4:\"true\";s:6:\"action\";s:26:\"workspace/packages/install\";s:8:\"register\";s:3:\"mgr\";s:5:\"topic\";s:53:\"/workspace/package/install/autoredirector-0.1.0-beta/\";s:8:\"lastSize\";s:15:\"[object Object]\";s:14:\"package_action\";i:0;}', 'autoRedirector', 'a:35:{s:2:\"id\";s:2:\"47\";s:10:\"repository\";s:1:\"1\";s:4:\"name\";s:14:\"autoRedirector\";s:9:\"createdby\";s:3:\"295\";s:9:\"createdon\";s:19:\"2014-02-18 16:12:55\";s:8:\"editedon\";s:19:\"0000-00-00 00:00:00\";s:7:\"license\";s:5:\"GPLv2\";s:10:\"screenshot\";s:0:\"\";s:9:\"downloads\";s:4:\"1703\";s:8:\"approved\";s:1:\"1\";s:6:\"active\";s:1:\"1\";s:7:\"package\";s:2:\"47\";s:7:\"version\";s:5:\"0.1.0\";s:13:\"version_major\";s:1:\"0\";s:13:\"version_minor\";s:1:\"1\";s:13:\"version_patch\";s:1:\"0\";s:7:\"release\";s:4:\"beta\";s:13:\"release_index\";s:0:\"\";s:9:\"signature\";s:25:\"autoredirector-0.1.0-beta\";s:12:\"instructions\";s:0:\"\";s:9:\"changelog\";s:1009:\"Changelog for autoRedirector.<br />\n<br />\n0.1.0 (18.08.2015)<br />\n==============<br />\n- Fix work with cyrillic urls<br />\n<br />\n0.0.9<br />\n==============<br />\n- Fix work with different objectTypes of resources<br />\n<br />\n0.0.8<br />\n==============<br />\n- Fix empty id:IN when resource is not container<br />\n<br />\n0.0.7<br />\n==============<br />\n- Correct russian lexicon<br />\n<br />\n0.0.6<br />\n==============<br />\n- Added multiselect and multiremove for rules<br />\n<br />\n0.0.5<br />\n==============<br />\n- Property &#039;old_uri&#039; setings anyway (even on created res)<br />\n<br />\n0.0.4<br />\n==============<br />\n- Fixed selecting child resources, when context_key != &#039;web&#039;<br />\n<br />\n0.0.3<br />\n==============<br />\n- Fixed selecting child resources on OnBeforeDocFormSave and OnDocFormSave<br />\n<br />\n0.0.2<br />\n==============<br />\n- Changed event, when start redirecting from OnHandleRequest to PageNotFound<br />\n<br />\n0.0.1<br />\n==============<br />\n- First beta.\";s:10:\"releasedby\";s:3:\"295\";s:10:\"releasedon\";s:19:\"2015-08-20 15:21:09\";s:16:\"minimum_supports\";s:3:\"2.2\";s:8:\"supports\";s:0:\"\";s:11:\"minimum_php\";s:0:\"\";s:10:\"deprecated\";s:1:\"0\";s:10:\"version_id\";s:3:\"593\";s:6:\"author\";s:19:\"Илья Уткин\";s:11:\"