              var trail= bc.data.trail;\n                    trail.pop();\n\n                    if (trail.length > 1) {\n                        last = trail[trail.length - 1];\n\n                        if (last != undefined && last.rec != undefined) {\n                            bc.data.trail.pop();\n                            bc.data.trail.shift();\n                            bc.updateDetail(bc.data);\n\n                            var grid = Ext.getCmp(\'modx-package-grid\');\n                            grid.install(last.rec);\n                            return;\n                        }\n                    }\n\n                    this.activate();\n					Ext.getCmp(\'modx-package-grid\').refresh();\n                },scope:this}\n                ,\'failure\': {fn:function() {\n                    this.activate();\n                },scope:this}\n            }\n        });\n\n        return true;\n	}\";s:8:\"disabled\";s:5:\"false\";s:5:\"scope\";s:15:\"[object Object]\";s:9:\"autoWidth\";s:4:\"true\";s:10:\"autoHeight\";s:4:\"true\";s:8:\"minWidth\";s:2:\"75\";s:10:\"removeMode\";s:9:\"container\";s:10:\"hideParent\";s:4:\"true\";s:6:\"events\";s:15:\"[object Object]\";s:7:\"ownerCt\";s:15:\"[object Object]\";s:9:\"container\";s:15:\"[object Object]\";s:8:\"rendered\";s:4:\"true\";s:8:\"template\";s:15:\"[object Object]\";s:5:\"btnEl\";s:15:\"[object Object]\";s:4:\"mons\";s:15:\"[object Object]\";s:2:\"el\";s:15:\"[object Object]\";s:4:\"icon\";s:0:\"\";s:7:\"iconCls\";s:0:\"\";s:8:\"boxReady\";s:4:\"true\";s:11:\"useSetClass\";s:4:\"true\";s:6:\"oldCls\";s:12:\"x-btn-noicon\";s:3:\"doc\";s:15:\"[object Object]\";s:19:\"monitoringMouseOver\";s:4:\"true\";s:6:\"action\";s:26:\"workspace/packages/install\";s:8:\"register\";s:3:\"mgr\";s:5:\"topic\";s:42:\"/workspace/package/install/jevix-1.2.2-pl/\";s:8:\"lastSize\";s:15:\"[object Object]\";s:14:\"package_action\";i:0;}', 'Jevix', 'a:35:{s:2:\"id\";s:2:\"12\";s:10:\"repository\";s:1:\"1\";s:4:\"name\";s:5:\"Jevix\";s:9:\"createdby\";s:1:\"6\";s:9:\"createdon\";s:19:\"2013-05-24 21:13:12\";s:8:\"editedon\";s:19:\"0000-00-00 00:00:00\";s:7:\"license\";s:5:\"GPLv2\";s:10:\"screenshot\";s:0:\"\";s:9:\"downloads\";s:4:\"6476\";s:8:\"approved\";s:1:\"1\";s:6:\"active\";s:1:\"1\";s:7:\"package\";s:2:\"12\";s:7:\"version\";s:5:\"1.2.2\";s:13:\"version_major\";s:1:\"1\";s:13:\"version_minor\";s:1:\"2\";s:13:\"version_patch\";s:1:\"2\";s:7:\"release\";s:2:\"pl\";s:13:\"release_index\";s:0:\"\";s:9:\"signature\";s:14:\"jevix-1.2.2-pl\";s:12:\"instructions\";s:0:\"\";s:9:\"changelog\";s:1068:\"Changelog for Jevix.<br />\n<br />\n1.2.2 pl<br />\n==============<br />\n- Added new parameter escapeTags, disabled by default.<br />\n<br />\n1.2.1 pl<br />\n==============<br />\n- Improved default cfgSetAutoPregReplace for support of YouTube https.<br />\n<br />\n1.2.0 pl2<br />\n==============<br />\n- Fixed the punctuation at the end of the link.<br />\n- Fixed nested tags in a preformatted blocks.<br />\n- Support for MODX tags in a preformatted blocks.<br />\n- Improved checking of urls.<br />\n- Main class refactor.<br />\n<br />\n1.1.1<br />\n==============<br />\n- Fixed errors handling<br />\n<br />\n1.1.0<br />\n==============<br />\n- Updated Jevix class from LiveStreet CMS<br />\n- New parameter cfgSetTagBlockType for tags which do not need to insert  after.<br />\n- New parameter cfgSetAutoPregReplace for auto replace with support of regular expressions.<br />\n- Tuned default properties, enabled tables.<br />\n- Links are now supports modx tags, e.g. &#91;&#91;~1&#93;&#93;, &#91;&#91;+link&#93;&#93;<br />\n<br />\n1.0.0<br />\n==============<br />\n- Initial release.\";s:10:\"releasedby\";s:1:\"6\";s:10:\"releasedon\";s:19:\"2015-12-13 06:55:26\";s:16:\"minimum_supports\";s:3:\"2.2\";s:8:\"supports\";s:0:\"\";s:11:\"minimum_php\";s:0:\"\";s:10:\"deprecated\";s:1:\"0\";s:10:\"version_id\";s:3:\"776\";s:6:\"author\";s:29:\"Василий Наумкин\";s:11:\"description\";s:73:\"Фильтрация и типографирование контента\";s:5:\"price\";s:1:\"0\";s:12:\"display_name\";s:14:\"jevix-1.2.2-pl\";s:11:\"supports_db\";s:5:\"mysql\";s:8:\"location\";s:104:\"https://modstore.pro/extras/package/12?version_id=776&username=&api_key=&http_host=s11838.h9.modhost.pro\";s:4:\"file\";a:2:{s:8:\"location\";s:104:\"https://modstore.pro/extras/package/12?version_id=776&username=&api_key=&http_host=s11838.h9.modhost.pro\";s:9:\"transport\";s:4:\"true\";}}', 1, 2, 2, 'pl', 0);
