 MIGX.\r\nНеограниченное добавление полей.\r\nПри повторном открытии ресурса центрирует карту по метке.\";s:9:\"signature\";s:25:\"yandexcoordstv-1.0.0-beta\";s:13:\"initialConfig\";s:15:\"[object Object]\";s:4:\"text\";s:20:\"Продолжить\";s:2:\"id\";s:19:\"package-install-btn\";s:6:\"hidden\";s:5:\"false\";s:7:\"handler\";s:1741:\"function (va){\n        var r;\n        var g = Ext.getCmp(\'modx-package-grid\');\n        if (!g) return false;\n\n        if (va.signature != undefined && va.signature != \'\') {\n            r = {signature: va.signature};\n        } else {\n            r = g.menu.record.data ? g.menu.record.data : g.menu.record;\n        }\n		var topic = \'/workspace/package/install/\'+r.signature+\'/\';\n        g.loadConsole(Ext.getBody(),topic);\n\n		va = va || {};\n        Ext.apply(va,{\n            action: \'workspace/packages/install\'\n            ,signature: r.signature\n            ,register: \'mgr\'\n            ,topic: topic\n        });\n\n        MODx.Ajax.request({\n            url: MODx.config.connector_url\n            ,params: va\n            ,listeners: {\n                \'success\': {fn:function() {\n                    var bc = Ext.getCmp(\'packages-breadcrumbs\');\n                    var trail= bc.data.trail;\n                    trail.pop();\n\n                    if (trail.length > 1) {\n                        last = trail[trail.length - 1];\n\n                        if (last != undefined && last.rec != undefined) {\n                            bc.data.trail.pop();\n                            bc.data.trail.shift();\n                            bc.updateDetail(bc.data);\n\n                            var grid = Ext.getCmp(\'modx-package-grid\');\n                            grid.install(last.rec);\n                            return;\n                        }\n                    }\n\n                    this.activate();\n					Ext.getCmp(\'modx-package-grid\').refresh();\n                },scope:this}\n                ,\'failure\': {fn:function() {\n                    this.activate();\n                },scope:this}\n            }\n        });\n\n        return true;\n	}\";s:8:\"disabled\";s:5:\"false\";s:5:\"scope\";s:15:\"[object Object]\";s:9:\"autoWidth\";s:4:\"true\";s:10:\"autoHeight\";s:4:\"true\";s:8:\"minWidth\";s:2:\"75\";s:10:\"removeMode\";s:9:\"container\";s:10:\"hideParent\";s:4:\"true\";s:6:\"events\";s:15:\"[object Object]\";s:7:\"ownerCt\";s:15:\"[object Object]\";s:9:\"container\";s:15:\"[object Object]\";s:8:\"rendered\";s:4:\"true\";s:8:\"template\";s:15:\"[object Object]\";s:5:\"btnEl\";s:15:\"[object Object]\";s:4:\"mons\";s:15:\"[object Object]\";s:2:\"el\";s:15:\"[object Object]\";s:4:\"icon\";s:0:\"\";s:7:\"iconCls\";s:0:\"\";s:8:\"boxReady\";s:4:\"true\";s:11:\"useSetClass\";s:4:\"true\";s:6:\"oldCls\";s:12:\"x-btn-noicon\";s:3:\"doc\";s:15:\"[object Object]\";s:19:\"monitoringMouseOver\";s:4:\"true\";s:6:\"action\";s:26:\"workspace/packages/install\";s:8:\"register\";s:3:\"mgr\";s:5:\"topic\";s:53:\"/workspace/package/install/yandexcoordstv-1.0.0-beta/\";s:8:\"lastSize\";s:15:\"[object Object]\";s:14:\"package_action\";i:0;}', 'YandexCoordsTv', 'a:35:{s:2:\"id\";s:3:\"267\";s:10:\"repository\";s:1:\"1\";s:4:\"name\";s:14:\"YandexCoordsTv\";s:9:\"createdby\";s:4:\"4412\";s:9:\"createdon\";s:19:\"2017-05-29 17:39:06\";s:8:\"editedon\";s:19:\"0000-00-00 00:00:00\";s:7:\"license\";s:5:\"GPLv2\";s:10:\"screenshot\";s:0:\"\";s:9:\"downloads\";s:2:\"59\";s:8:\"approved\";s:1:\"1\";s:6:\"active\";s:1:\"1\";s:7:\"package\";s:3:\"267\";s:7:\"version\";s:5:\"1.0.0\";s:13:\"version_major\";s:1:\"1\";s:13:\"version_minor\";s:1:\"0\";s:13:\"version_patch\";s:1:\"0\";s:7:\"release\";s:4:\"beta\";s:13:\"release_index\";s:0:\"\";s:9:\"signature\";s:25:\"yandexcoordstv-1.0.0-beta\";s:12:\"instructions\";s:0:\"\";s:9:\"changelog\";s:0:\"\";s:10:\"releasedby\";s:4:\"4412\";s:10:\"releasedon\";s:19:\"2017-05-29 17:39:06\";s:16:\"minimum_supports\";s:3:\"2.5\";s:8:\"supports\";s